  (93880, '5b8c037b-4d59-4a87-93d9-47ef6ac0045d'::uuid, 'POTATO SH-POLYPEPTIDE-11', 'POTATO SH-POLYPEPTIDE-11', NULL, NULL, 'Transgenic Potato sh-Polypeptide-11', 'Potato sh-Polypeptide-11 is a single chain recombinant human peptide, produced by potato, Solanum tuberosum, after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Acidic Fibroblast Growth Factor 1. It contains a maximum of 155 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"5b8c037b-4d59-4a87-93d9-47ef6ac0045d","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POTATO SH-POLYPEPTIDE-11"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Transgenic Potato sh-Polypeptide-11"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Potato sh-Polypeptide-11 is a single chain recombinant human peptide, produced by potato, Solanum tuberosum, after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Acidic Fibroblast Growth Factor 1. It contains a maximum of 155 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["2E2A0163F9E0205E4D39614CEF36A85E"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POTATO SH-POLYPEPTIDE-11"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["93880"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN PROTECTING"],"esDA_IngestDate":["2023-05-22T16:49:19.764+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:49:19.726+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"5b8c037b-4d59-4a87-93d9-47ef6ac0045d. Available at: urn:test"}'::jsonb),
