  (93917, 'b6b38971-5dc0-42cf-a3b8-c04904011b99'::uuid, 'NICOTIANA BENTHAMIANA HEXAPEPTIDE-40 SH-POLYPEPTIDE-86', 'NICOTIANA BENTHAMIANA HEXAPEPTIDE-40 SH-POLYPEPTIDE-86', NULL, NULL, NULL, 'Nicotiana Benthamiana Hexapeptide-40 sh-Polypeptide-86 is a fusion peptide of Hexapeptide-40 with a single chain recombinant human peptide, produced by transgenic  Nicotiana benthamiana  after the transient expression or stable insertion of a copy of a human gene into its DNA. The starting human gene is synthesized to be identical to the human gene which codes for Follistatin and contains a maximum of 344 amino acids. The fusion peptide contains 294 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b6b38971-5dc0-42cf-a3b8-c04904011b99","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["NICOTIANA BENTHAMIANA HEXAPEPTIDE-40 SH-POLYPEPTIDE-86"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Nicotiana Benthamiana Hexapeptide-40 sh-Polypeptide-86 is a fusion peptide of Hexapeptide-40 with a single chain recombinant human peptide, produced by transgenic  Nicotiana benthamiana  after the transient expression or stable insertion of a copy of a human gene into its DNA. The starting human gene is synthesized to be identical to the human gene which codes for Follistatin and contains a maximum of 344 amino acids. The fusion peptide contains 294 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["547155188CBE256E017E90440BC1F865"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["NICOTIANA BENTHAMIANA HEXAPEPTIDE-40 SH-POLYPEPTIDE-86"],"esST_FileName":["file.txt"],"casNo":["117628-82-7"],"substanceId":["93917"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HAIR CONDITIONING"],"esDA_IngestDate":["2023-05-22T16:49:52.960+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:49:52.930+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"b6b38971-5dc0-42cf-a3b8-c04904011b99. Available at: urn:test"}'::jsonb),
