  (94040, 'fbb032e6-4822-4dd6-b188-f84a01483f97'::uuid, 'OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-85 DIPEPTIDE-19 HEXAPEPTIDE-40', 'OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-85 DIPEPTIDE-19 HEXAPEPTIDE-40', NULL, NULL, NULL, 'Oligopeptide-91 Dipeptide-19 sh-Polypeptide-85 Dipeptide-19 Hexapeptide-40 is a single chain synthetic fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-85, Oligopeptide-91, Dipeptide-19, and Hexapeptide-40. The fusion peptide contains 239 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"fbb032e6-4822-4dd6-b188-f84a01483f97","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-85 DIPEPTIDE-19 HEXAPEPTIDE-40"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Oligopeptide-91 Dipeptide-19 sh-Polypeptide-85 Dipeptide-19 Hexapeptide-40 is a single chain synthetic fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-85, Oligopeptide-91, Dipeptide-19, and Hexapeptide-40. The fusion peptide contains 239 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["98C649C22FBFED6CE77C6AF58A5B071D"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-85 DIPEPTIDE-19 HEXAPEPTIDE-40"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94040"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HAIR CONDITIONING"],"esDA_IngestDate":["2023-05-22T16:51:28.135+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:51:28.097+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"fbb032e6-4822-4dd6-b188-f84a01483f97. Available at: urn:test"}'::jsonb),
  (94041, '48e56f36-3340-49e3-a4af-d08dd59d049f'::uuid, 'TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 METHIONYL OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-85 DIPEPTIDE-34 OLIGOPEPTIDE-91', 'TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 METHIONYL OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-85 DIPEPTIDE-34 OLIGOPEPTIDE-91', NULL, NULL, NULL, 'Tripeptide-46 Hexapeptide-40 Decapeptide-27 Methionyl Oligopeptide-91 Dipeptide-19 sh-Polypeptide-85 Dipeptide-34 Oligopeptide-91 is a single chain recombinant fusion peptide produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-85, Tripeptide-46, Hexapeptide-40, Decapeptide-27, Oligopeptide-91, Dipeptide-19, and {29889; Dipeptide-34} with the initiation code for methionine. The fusion peptide contains 273 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"48e56f36-3340-49e3-a4af-d08dd59d049f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 METHIONYL OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-85 DIPEPTIDE-34 OLIGOPEPTIDE-91"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Tripeptide-46 Hexapeptide-40 Decapeptide-27 Methionyl Oligopeptide-91 Dipeptide-19 sh-Polypeptide-85 Dipeptide-34 Oligopeptide-91 is a single chain recombinant fusion peptide produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-85, Tripeptide-46, Hexapeptide-40, Decapeptide-27, Oligopeptide-91, Dipeptide-19, and {29889; Dipeptide-34} with the initiation code for methionine. The fusion peptide contains 273 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["827C0EB79629D7EBB0E47E90C5623B3C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 METHIONYL OLIGOPEPTIDE-91 DIPEPTIDE-19 SH-POLYPEPTIDE-85 DIPEPTIDE-34 OLIGOPEPTIDE-91"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94041"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HAIR CONDITIONING"],"esDA_IngestDate":["2023-05-22T16:51:28.399+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:51:28.367+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"48e56f36-3340-49e3-a4af-d08dd59d049f. Available at: urn:test"}'::jsonb),
