  (94169, 'f48c4648-b53b-42de-a8db-30ea898b9916'::uuid, 'METHIONYL SH-POLYPEPTIDE-92', 'METHIONYL SH-POLYPEPTIDE-92', NULL, NULL, NULL, 'Methionyl sh-Polypeptide-92 is a single chain synthetic fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-92 with the initiation code for methionine. The fusion peptide contains 110 amino acids and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"f48c4648-b53b-42de-a8db-30ea898b9916","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHIONYL SH-POLYPEPTIDE-92"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methionyl sh-Polypeptide-92 is a single chain synthetic fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-92 with the initiation code for methionine. The fusion peptide contains 110 amino acids and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["BF45B128498022AA5B165F1E44F1C65F"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["METHIONYL SH-POLYPEPTIDE-92"],"esST_FileName":["file.txt"],"casNo":[],"subs