  (94177, '419e56fe-ccaf-4e5c-92a3-d450db144423'::uuid, 'IMMORTALIZED HUMAN TOOTH PULP STEM CELL CONDITIONED MEDIA', 'IMMORTALIZED HUMAN TOOTH PULP STEM CELL CONDITIONED MEDIA', NULL, NULL, NULL, 'Immortalized Human Tooth Pulp Stem Cell Conditioned Media is the growth media removed from cultures of cells isolated from human tooth pulp tissue after several days of growth. The cells are immortalized by the insertion of the human papillomavirus E6 and E7 genes, and hTERT gene. The starting media is either Dulbecco''s Modified Eagle Medium which may or may not contain fetal bovine serum, or a serum-free nutrient media.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"419e56fe-ccaf-4e5c-92a3-d450db144423","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":8.445373,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["IMMORTALIZED HUMAN TOOTH PULP STEM CELL CONDITIONED MEDIA"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Immortalized Human Tooth Pulp Stem Cell Conditioned Media is the growth media removed from cultures of cells isolated from human tooth pulp tissue after several days of growth. The cells are immortalized by the insertion of the human papillomavirus E6 and E7 genes, and hTERT gene. The starting media is either Dulbecco''s Modified Eagle Medium which may or may not contain fetal bovine serum, or a serum-free nutrient media."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"refer