  (94199, 'b64c046d-d944-4048-a692-d0cd6bc9dda5'::uuid, 'ETHYL CARBAZIDO HYALURONATE SH-OLIGOPEPTIDE-1 SH-POLYPEPTIDE-94 DIPEPTIDE-35 SH-POLYPEPTIDE-94 SH-POLYPEPTIDE-95', 'ETHYL CARBAZIDO HYALURONATE SH-OLIGOPEPTIDE-1 SH-POLYPEPTIDE-94 DIPEPTIDE-35 SH-POLYPEPTIDE-94 SH-POLYPEPTIDE-95', NULL, NULL, NULL, 'Ethyl Carbazido Hyaluronate sh-Oligopeptide-1 sh-Polypeptide-94 Dipeptide-35 sh-Polypeptide-94 sh-Polypeptide-95 is a single chain recombinant fusion peptide, produced by fermentation in Chinese hamster ovary cells (CHO). The starting gene is synthesized by the fusion of the gene from sh-Oligopeptide-1, sh-Polypeptide-94, Dipeptide-35, and sh-Polypeptide-95. The fusion peptide is conjugated with ethyl carbazido hyaluronate, and it consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b64c046d-d944-4048-a692-d0cd6bc9dda5","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["ETHYL CARBAZIDO HYALURONATE SH-OLIGOPEPTIDE-1 SH-POLYPEPTIDE-94 DIPEPTIDE-35 SH-POLYPEPTIDE-94 SH-POLYPEPTIDE-95"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Ethyl Carbazido Hyaluronate sh-Oligopeptide-1 sh-Polypeptide-94 Dipeptide-35 sh-Polypeptide-94 sh-Polypeptide-95 is a single chain recombinant fusion peptide, produced by fermentation in Chinese hamster ovary cells (CHO). The starting gene is synthesized by the fusion of the gene from sh-Oligopeptide-1, sh-Polypeptide-94, Dipeptide-35, and sh-Polypeptide-95. The fusion peptide is conjugated with ethyl carbazido hyaluronate, and it consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["DE412DB67C7E337DAF0FB9D3C05FB514"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["ETHYL CARBAZIDO HYALURONATE SH-OLIGOPEPTIDE-1 SH-POLYPEPTIDE-94 DIPEPTIDE-35 SH-POLYPEPTIDE-94 SH-POLYPEPTIDE-95"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94199"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN PROTECTING"],"esDA_IngestDate":["2023-05-22T16:47:59.674+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:47:59.643+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"b64c046d-d944-4048-a692-d0cd6bc9dda5. Available at: urn:test"}'::jsonb),
