  (94240, '0dd925c8-a027-4ff7-935d-80344650ba69'::uuid, 'BIS-HEA IPDI/PPG-53 COPOLYMER', 'BIS-HEA IPDI/PPG-53 COPOLYMER', NULL, NULL, NULL, 'Bis-HEA IPDI/PPG-53 Copolymer is the polymer made by the reaction of PPG-53 and Isophorone Diisocyanate (IPDI), end-capped with 2-hydroxyethylacrylate (HEA).', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"0dd925c8-a027-4ff7-935d-80344650ba69","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-HEA IPDI/PPG-53 COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-HEA IPDI/PPG-53 Copolymer is the polymer made by the reaction of PPG-53 and Isophorone Diisocyanate (IPDI), end-capped with 2-hydroxyethylacrylate (HEA)."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["93C44122C0A12EF6D5441FA84091EB51"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["BIS-HEA IPDI/PPG-53 COPOLYMER"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94240"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["BINDING"],"esDA_IngestDate":["2023-05-22T16:46:32.885+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T