  (94241, 'abd611f3-60d2-49ff-a714-5d7b45b74995'::uuid, 'POLYSILICONE-33', 'POLYSILICONE-33', NULL, NULL, NULL, 'Polysilicone-33 is a polysilsesquioxane that also contains dimethyl siloxane groups. It is produced by the hydrolysis and condensation of dimethyldimethoxysilane, Methyltrimethoxysilane, propyltrimethoxysilane, Aminopropyl Triethoxysilane, octyltriethoxysilane, and phenyltrimethoxysilane', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"abd611f3-60d2-49ff-a714-5d7b45b74995","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYSILICONE-33"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polysilicone-33 is a polysilsesquioxane that also contains dimethyl siloxane groups. It is produced by the hydrolysis and condensation of dimethyldimethoxysilane, Methyltrimethoxysilane, propyltrimethoxysilane, Aminopropyl Triethoxysilane, octyltriethoxysilane, and phenyltrimethoxysilane"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["814FE3044A1A2A42C00EBD974D44BB2F"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYSILICONE-33"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94241"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],