  (94243, 'c5f340a7-ba1c-4811-8ab9-a9cc3c8dda9b'::uuid, 'METHYLDIHYDROXYPROPYLAMIDO UNDECYL DECYL DIMETHICONE', 'METHYLDIHYDROXYPROPYLAMIDO UNDECYL DECYL DIMETHICONE', NULL, NULL, NULL, 'Methyldihydroxypropylamido Undecyl Decyl Dimethicone is the siloxane polymer made by reacting Hydrogen Dimethicone with Decene and 3-[N-methyl-N-(10-undecenoyl)amido]-1,2-propanediol.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"c5f340a7-ba1c-4811-8ab9-a9cc3c8dda9b","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9887555,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHYLDIHYDROXYPROPYLAMIDO UNDECYL DECYL DIMETHICONE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methyldihydroxypropylamido Undecyl Decyl Dimethicone is the siloxane polymer made by reacting Hydrogen Dimethicone with Decene and 3-[N-methyl-N-(10-undecenoyl)amido]-1,2-propanediol."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["296E38955D3B76756FB2B559D99BE39E"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["METHYLDIHYDROXYPROPYLAMIDO UNDECYL DECYL DIMETHICONE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94243"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SURFACTANT - EMULSIFYING","SURFACTANT - CLEAN