  (94244, '9c7ee8ca-020b-4242-ab6e-ff6ca46dd703'::uuid, 'POTASSIUM ACRYLATE CROSSPOLYMER', 'POTASSIUM ACRYLATE CROSSPOLYMER', NULL, NULL, '2-Propenoic acid, polymer with N,N''-methylenebis[2-propenamide] and potassium 2-propenoate (1:1)', 'Potassium Acrylate Crosspolymer is the potassium salt of a polymer of Acrylic Acid crosslinked with N,N''-methylenebisacrylamide.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"9c7ee8ca-020b-4242-ab6e-ff6ca46dd703","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":7.442367,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POTASSIUM ACRYLATE CROSSPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["2-Propenoic acid, polymer with N,N''-methylenebis[2-propenamide] and potassium 2-propenoate (1:1)"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Potassium Acrylate Crosspolymer is the potassium salt of a polymer of Acrylic Acid crosslinked with N,N''-methylenebisacrylamide."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["26558F412F61850C01A71774DC3AB22D"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POTASSIUM ACRYLATE CROSSPOLYMER"],"esST_FileName":["file.txt"],"casNo":["86416-97-9"],"substanceId":["94244"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ABSORBENT"],"esDA_IngestDate":["