  (94287, 'b67f575c-104a-4825-89a6-1e832ed41791'::uuid, 'BARLEY SH-POLYPEPTIDE-9', 'BARLEY SH-POLYPEPTIDE-9', NULL, NULL, 'Transgenic Barley sh-Polypeptide-9,Vasculotropin (INN)', 'Barley sh-Polypeptide-9 is a single chain recombinant human peptide, produced by barley plants after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Vascular Endothelial Growth Factor A. It contains a maximum of 412 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b67f575c-104a-4825-89a6-1e832ed41791","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BARLEY SH-POLYPEPTIDE-9"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Transgenic Barley sh-Polypeptide-9,Vasculotropin (INN)"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Barley sh-Polypeptide-9 is a single chain recombinant human peptide, produced by barley plants after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Vascular Endothelial Growth Factor A. It contains a maximum of 412 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["F9D2885EEC40CB743D3EF77E328426AC"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["BARLEY SH-POLYPEPTIDE-9"],"esST_FileName":["file.txt"],"casNo":["127464-60-2"],"substanceId":["94287"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING"],"esDA_IngestDate":["2023-05-22T16:50:12.947+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:50:12.908+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"b67f575c-104a-4825-89a6-1e832ed41791. Available at: urn:test"}'::jsonb),
  (94288, '3935d324-a26b-4135-b889-ea175de74df5'::uuid, 'BARLEY SH-POLYPEPTIDE-8', 'BARLEY SH-POLYPEPTIDE-8', NULL, NULL, 'Transgenic Barley sh-Polypeptide-8', 'Barley sh-Polypeptide-8 is a single chain recombinant human peptide, produced by barley plants after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Platelet Derived Growth Factor. It contains a maximum of 241 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper 20 sequence of the standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"3935d324-a26b-4135-b889-ea175de74df5","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BARLEY SH-POLYPEPTIDE-8"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Transgenic Barley sh-Polypeptide-8"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Barley sh-Polypeptide-8 is a single chain recombinant human peptide, produced by barley plants after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Platelet Derived Growth Factor. It contains a maximum of 241 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper 20 sequ