  (94299, '90efcca7-9e0c-4ec2-aa38-56682d139aa3'::uuid, 'RH-RICE EXTRACT', 'RH-RICE EXTRACT', NULL, NULL, 'rh-Transgenic Rice Extract', 'rh-Rice Extract is the extract of rice,  Oryza sativa  , obtained after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is directly isolated from a human cell which codes for Insulin-Like Growth Factor 1.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"90efcca7-9e0c-4ec2-aa38-56682d139aa3","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["RH-RICE EXTRACT"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["rh-Transgenic Rice Extract"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["rh-Rice Extract is the extract of rice,  Oryza sativa  , obtained after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is directly isolated from a human cell which codes for Insulin-Like Growth Factor 1."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["EEBAA1CDFBF86EE3C226A69D9227398B"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["RH-RICE EXTRACT"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94299"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":