no acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["58ECC09CD5036384216B2650126A741C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["TETRAPEPTIDE-39 HEXAPEPTIDE-40 NONAPEPTIDE-20 SR-SPIDER POLYPEPTIDE-3 DECAPEPTIDE-30"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94306"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HAIR CONDITIONING","SKIN PROTECTING"],"esDA_IngestDate":["2023-05-22T16:50:31.046+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:50:30.940+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"0c4662ae-8d14-4bd8-bda0-23c81f255596. Available at: urn:test"}'::jsonb),
