  (94324, '26efe8aa-bf4d-4467-96ec-644046a354bb'::uuid, 'SH-OLIGOPEPTIDE-82 AMIDE', 'SH-OLIGOPEPTIDE-82 AMIDE', NULL, NULL, 'Beta Defensin 103', 'sh-Oligopeptide-82 Amide is a single chain human peptide produced synthetically to be identical to a portion of the protein, Beta-Defensin 3 and contains 15 amino acids in which the C-terminus is an amide. Beta-Defensin 3 contains a maximum of 67 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"26efe8aa-bf4d-4467-96ec-644046a354bb","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.3742867,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-OLIGOPEPTIDE-82 AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Beta Defensin 103"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Oligopeptide-82 Amide is a single chain human peptide produced synthetically to be identical to a portion of the protein, Beta-Defensin 3 and contains 15 amino acids in which the C-terminus is an amide. Beta-Defensin 3 contains a maximum of 67 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["21E9EF48CBFE3F96C05B6388372A5BE3"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officia