  (94356, 'a6febed4-a1a2-477f-a5c4-22a4180519c5'::uuid, 'S-CENTIPEDE OLIGOPEPTIDE-1 AMIDE', 'S-CENTIPEDE OLIGOPEPTIDE-1 AMIDE', NULL, NULL, NULL, 's-Centipede Oligopeptide-1 Amide is a single chain centipede protein produced synthetically to be identical to a portion of the protein, Scolopendrasin-I which is found in the centipede,  Scolopendra subspinipes mutilans.  The peptide contains 14 amino acids in which the C-terminus is an amide. Scolopendrasin-I contains a maximum of 45 amino acids consisting of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a6febed4-a1a2-477f-a5c4-22a4180519c5","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-CENTIPEDE OLIGOPEPTIDE-1 AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Centipede Oligopeptide-1 Amide is a single chain centipede protein produced synthetically to be identical to a portion of the protein, Scolopendrasin-I which is found in the centipede,  Scolopendra subspinipes mutilans.  The peptide contains 14 amino acids in which the C-terminus is an amide. Scolopendrasin-I contains a maximum of 45 amino acids consisting of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["D67B56FF80AEB3FAA9112B18B27CCFE1"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration