  (94357, 'f8b2105b-dd76-4e2a-b6a1-d5be1465cfdd'::uuid, 'HUMAN ADIPOSE STROMAL CELL/HUMAN HAIR DERMAL PAPILLA CELL CONDITIONED MEDIA', 'HUMAN ADIPOSE STROMAL CELL/HUMAN HAIR DERMAL PAPILLA CELL CONDITIONED MEDIA', NULL, NULL, NULL, 'Human Adipose Stromal Cell/Human Hair Dermal Papilla Cell Conditioned Media is the growth media removed from cultures of human adipose stromal cells and human dermal papilla cells after several days of growth. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"f8b2105b-dd76-4e2a-b6a1-d5be1465cfdd","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["HUMAN ADIPOSE STROMAL CELL/HUMAN HAIR DERMAL PAPILLA CELL CONDITIONED MEDIA"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Human Adipose Stromal Cell/Human Hair Dermal Papilla Cell Conditioned Media is the growth media removed from cultures of human adipose stromal cells and human dermal papilla cells after several days of growth. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["4316A3BDB52A4952D5A2847E2C7AB79F"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y