  (94359, '70b324e2-0463-46cc-a50c-81798508940c'::uuid, 'SODIUM DACRYOPINAX SPATHULARIA/GLUCOSE FERMENT EXTRACT', 'SODIUM DACRYOPINAX SPATHULARIA/GLUCOSE FERMENT EXTRACT', NULL, NULL, NULL, 'Sodium Dacryopinax Spathularia/Glucose Ferment Extract is the extract of the sodium salt of the product obtained by the fermentation of glucose by the fungus,  Dacryopinax spathularia.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"70b324e2-0463-46cc-a50c-81798508940c","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.3742867,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SODIUM DACRYOPINAX SPATHULARIA/GLUCOSE FERMENT EXTRACT"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Sodium Dacryopinax Spathularia/Glucose Ferment Extract is the extract of the sodium salt of the product obtained by the fermentation of glucose by the fungus,  Dacryopinax spathularia."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["1FCD2924377418D32F5A15418BB35EAC"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SODIUM DACRYOPINAX SPATHULARIA/GLUCOSE FERMENT EXTRACT"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94359"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HUMECTANT","SKIN CONDITIONING"],"es