  (94391, '40a34bcf-e462-44e1-ae99-b522fc40e1a0'::uuid, 'DEER ANTLER CELL/SH-POLYPEPTIDE-1 CONDITIONED MEDIA', 'DEER ANTLER CELL/SH-POLYPEPTIDE-1 CONDITIONED MEDIA', NULL, NULL, NULL, 'Deer Antler Cell/sh-Polypeptide-1 Conditioned Media is the growth media removed from cultures containing sh-Polypeptide-1 with the cells isolated from deer antler after several days of growth.', NULL, NULL, 'Please consider whether entry 419 of Annex II to the Cosmetics Regulation 1223/2009 is applicable. According to entry 419, category 1 material and Category 2 material as defined in Articles 4 and 5 respectively of Regulation (EC) No 1774/2002, and ingredients derived therefrom are prohibited in cosmetics products. Regulation (EC) No 1774/2002 has been repealed and replaced by Regulation No. 1069/2009. For Category 1 and 2 materials in Regulation No. 1069/2009, please see Article 8 and 9, respectively.', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"40a34bcf-e462-44e1-ae99-b522fc40e1a0","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["DEER ANTLER CELL/SH-POLYPEPTIDE-1 CONDITIONED MEDIA"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Deer Antler Cell/sh-Polypeptide-1 Conditioned Media is the growth media removed from cultures containing sh-Polypeptide-1 with the cells isolated from deer antler after several days of growth."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["40a34bcf-e462-44e1-ae99-b522fc40e1a0"],"reference":["0CD40DE1213105BBF13CB6472B53CA47"],"co