  (94479, 'a68c96fc-021a-4105-a10f-34e7a1a296bb'::uuid, 'SH-POLYPEPTIDE-7 SH-OLIGOPEPTIDE-1', 'SH-POLYPEPTIDE-7 SH-OLIGOPEPTIDE-1', NULL, NULL, NULL, 'sh-Polypeptide-7 sh-Oligopeptide-1 is a single chain synthetic fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-7 and sh-Oligopeptide-1. The fusion peptide contains 244 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a68c96fc-021a-4105-a10f-34e7a1a296bb","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-7 SH-OLIGOPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-7 sh-Oligopeptide-1 is a single chain synthetic fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-7 and sh-Oligopeptide-1. The fusion peptide contains 244 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["95A17E317E7A6C84212FE210C16A7932"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJourn