  (94605, '6312263c-e8a1-4d5c-95d2-0b14fdea2949'::uuid, 'POLYURETHANE-74', 'POLYURETHANE-74', NULL, NULL, NULL, 'Polyurethane-74 is a copolymer formed by reacting Isophorone Diisocyanate (q.v.) with neopenyl glycol mono(hydroxypivalate) and a polyester pre-polymer that is made by condensing diethyl carbonate, Hexanediol, Glycol, and epsilon-caprolactone. The polymer is capped with 2-hydroxyethyl acrylate.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"6312263c-e8a1-4d5c-95d2-0b14fdea2949","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-74"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-74 is a copolymer formed by reacting Isophorone Diisocyanate (q.v.) with neopenyl glycol mono(hydroxypivalate) and a polyester pre-polymer that is made by condensing diethyl carbonate, Hexanediol, Glycol, and epsilon-caprolactone. The polymer is capped with 2-hydroxyethyl acrylate."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["36654F7D1017723D2E4015E6F04CD538"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-74"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94605"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInform