  (94643, '3ee61bcb-7732-439b-a7b8-4b4fba7dc73c'::uuid, 'DEER VELVET MESENCHYMAL CELL CONDITIONED MEDIA', 'DEER VELVET MESENCHYMAL CELL CONDITIONED MEDIA', NULL, NULL, NULL, 'Deer Velvet Mesenchymal Cell Conditioned Media is the growth media removed from cultures of mesenchymal cells isolated from deer antler velvet after several days of growth. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum.', NULL, NULL, 'Please consider whether entry 419 of Annex II to the Cosmetics Regulation 1223/2009 is applicable. According to entry 419, category 1 material and Category 2 material as defined in Articles 4 and 5 respectively of Regulation (EC) No 1774/2002, and ingredients derived therefrom are prohibited in cosmetics products. Regulation (EC) No 1774/2002 has been repealed and replaced by Regulation No. 1069/2009. For Category 1 and 2 materials in Regulation No. 1069/2009, please see Article 8 and 9, respectively.', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"3ee61bcb-7732-439b-a7b8-4b4fba7dc73c","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["DEER VELVET MESENCHYMAL CELL CONDITIONED MEDIA"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Deer Velvet Mesenchymal Cell Conditioned Media is the growth media removed from cultures of mesenchymal cells isolated from deer antler velvet after several days of growth. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8