  (94644, '5911f05b-e0be-4879-b34f-69fd970d4647'::uuid, 'ENTEROCOCCUS FAECIUM/LACTOBACILLUS/SALIX PURPUREA BARK/LEAF/STEM/WOOD/ASCORBIC ACID/ GLUCONOLACTONE FERMENT EXTRACT FILTRATE', 'Enterococcus Faecium/Lactobacillus/Salix Purpurea Bark/Leaf/Stem/Wood/Ascorbic Acid/ Gluconolactone Ferment Extract Filtrate', NULL, NULL, NULL, 'Enterococcus Faecium/Lactobacillus/Salix Purpurea Bark/Leaf/Stem/Wood/Ascorbic Acid/ Gluconolactone Ferment Extract Filtrate is a filtrate of the extract of the product obtained by the fermentation of the bark, leaves, stems and wood of Salix purpurea, Ascorbic Acid and Gluconolactone by the microorganisms Enterococcus faecium and Lactobacillus.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"5911f05b-e0be-4879-b34f-69fd970d4647","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":7.7267504,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Enterococcus Faecium/Lactobacillus/Salix Purpurea Bark/Leaf/Stem/Wood/Ascorbic Acid/ Gluconolactone Ferment Extract Filtrate"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Enterococcus Faecium/Lactobacillus/Salix Purpurea Bark/Leaf/Stem/Wood/Ascorbic Acid/ Gluconolactone Ferment Extract Filtrate is a filtrate of the extract of the product obtained by the fermentation of the bark, leaves, stems and wood of Salix purpurea, Ascorbic Acid and Gluconolactone by the microorganisms Enterococcus faecium and Lactobacillus."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["5911f05b-e0be-4879-b34f-69fd970d4647"],"reference":["1F877E3D0E1C