  (94737, 'a8bf8773-29c7-4a5d-8b34-92ee76b96688'::uuid, 'NICOTIANA BENTHAMIANA SH-POLIPEDTIDE-45', 'NICOTIANA BENTHAMIANA SH-POLIPEDTIDE-45', NULL, NULL, NULL, 'Nicotiana Benthamiana sh-Polypeptide-45 is a single chain recombinant human peptide, produced by  Nicotiana benthamiana  after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Granulocyte Macrophage Colony Stimulating Factor. It contains a maximum of 144 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a8bf8773-29c7-4a5d-8b34-92ee76b96688","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["NICOTIANA BENTHAMIANA SH-POLIPEDTIDE-45"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Nicotiana Benthamiana sh-Polypeptide-45 is a single chain recombinant human peptide, produced by  Nicotiana benthamiana  after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Granulocyte Macrophage Colony Stimulating Factor. It contains a maximum of 144 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["97A761ED9B437176D961C08A89DAFAB5"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["NICOTIANA BENTHAMIANA SH-POLIPEDTIDE-45"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94737"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING"],"esDA_IngestDate":["2023-05-23T07:49:03.485+0200"],"currentVersion":["1"],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:49:03.452+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"a8bf8773-29c7-4a5d-8b34-92ee76b96688. Available at: urn:test"}'::jsonb),
