  (94820, '814cc0ee-c82b-4c11-8ae8-92a554654f3b'::uuid, 'S-MUSSEL OLIGOPEPTIDE-2', 'S-MUSSEL OLIGOPEPTIDE-2', NULL, NULL, NULL, 's-Mussel Oligopeptide-2 is a single chain protein containing 18 amino acids. It is synthetically produced based on a sequence from Adhesive Plaque Matrix Protein which is found in the mussel, Mytilus galloprovincialis. Adhesive Plaque Matrix Protein contains 875 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"814cc0ee-c82b-4c11-8ae8-92a554654f3b","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.3742867,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-MUSSEL OLIGOPEPTIDE-2"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Mussel Oligopeptide-2 is a single chain protein containing 18 amino acids. It is synthetically produced based on a sequence from Adhesive Plaque Matrix Protein which is found in the mussel, Mytilus galloprovincialis. Adhesive Plaque Matrix Protein contains 875 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["F6EE625B939FAB18C14C26C04A9905A9"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":[