  (94834, '869385c9-638d-4adb-ab15-6003027f81cc'::uuid, 'SR-ESCHERICHIA COLI POLYPEPTIDE-1 TRIPEPTIDE-64 SR-SILKWORM POLYPEPTIDE-1 SH-POLYPEPTIDE-50 OLIGOPEPTIDE-144 HEXAPEPTIDE-40', 'SR-ESCHERICHIA COLI POLYPEPTIDE-1 TRIPEPTIDE-64 SR-SILKWORM POLYPEPTIDE-1 SH-POLYPEPTIDE-50 OLIGOPEPTIDE-144 HEXAPEPTIDE-40', NULL, NULL, NULL, 'sr-Escherichia Coli Polypeptide-1 Tripeptide-64 sr-Silkworm Polypeptide-1 sh-Polypeptide-50 Oligopeptide-144 Hexapeptide-40 is a single chain synthetic fusion peptide produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sr-Escherichia Coli Polypeptide-1, sr-Silkworm Polypeptide-1, Tripeptide-64, sh-Polypeptide-50, Oligopeptide-144 and Hexapeptide-40. The fusion peptide contains 884 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"869385c9-638d-4adb-ab15-6003027f81cc","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.3742867,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SR-ESCHERICHIA COLI POLYPEPTIDE-1 TRIPEPTIDE-64 SR-SILKWORM POLYPEPTIDE-1 SH-POLYPEPTIDE-50 OLIGOPEPTIDE-144 HEXAPEPTIDE-40"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-Escherichia Coli Polypeptide-1 Tripeptide-64 sr-Silkworm Polypeptide-1 sh-Polypeptide-50 Oligopeptide-144 Hexapeptide-40 is a single chain synthetic fusion peptide produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sr-Escherichia Coli Polypeptide-1, sr-Silkworm Polypeptide-1, Tripeptide-64, sh-Polypeptide-50, Oligopeptide-144 and Hexapeptide-40. The fusion peptide contains 884 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["5C3B9A856D543A4734970BDBC8937896"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SR-ESCHERICHIA COLI POLYPEPTIDE-1 TRIPEPTIDE-64 SR-SILKWORM POLYPEPTIDE-1 SH-POLYPEPTIDE-50 OLIGOPEPTIDE-144 HEXAPEPTIDE-40"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["94834"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HUMECTANT","SKIN CONDITIONING"],"esDA_IngestDate":["2023-05-23T07:48:47.860+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:48:47.832+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"869385c9-638d-4adb-ab15-6003027f81cc. Available at: urn:test"}'::jsonb),
  (94835, '3074883d-5c9a-4d8f-bd11-3bf53f227957'::uuid, 'ACETYL S-FEA''S VIPER PENTAPEPTIDE-1 AMIDE', 'ACETYL S-FEA''S VIPER PENTAPEPTIDE-1 AMIDE', NULL, NULL, NULL, 'Acetyl s-FEA''s Viper Pentapeptide-1 Amide is the product obtained by the acetylation of a single chain Fea''s viper peptide produced synthetically to be identical to a portion of the protein, Azemiopsin, which is found in the viper, Azemiops feae. The peptide contains 5 amino acids consisting of lysine, proline and tryptophan, in which the C-terminus is an amide. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"3074883d-5c9a-4d8f-bd11-3bf53f227957","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["ACETYL S-FEA''S VIPER PENTAPEPTIDE-1 AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Acetyl s-FEA''s Viper Pentapeptide-1 Amide is the product obtained by the acetylation of a single chain Fea''s viper peptide produced synthetically to be identical to a portion of the protein, Azemiopsin, which is found in the viper, Azemiops feae. The peptide contains 5 amino acids consisting of lysine, proline and tryptophan, in which the C-terminus is an amide. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["882CAB