  (94933, '2e73345f-ff42-4ade-82f8-a5c1932c0bda'::uuid, 'POLYSILICONE-34', 'POLYSILICONE-34', NULL, NULL, NULL, 'Polysilicone-34 is a complex polymeric salt made by reacting Acrylates/C10-30 Alkyl Acrylate Crosspolymer with a silicone polymer that is prepared by reacting Bis-Hydroxypropyl Dimethicone with 2,3-epoxypropylamine followed by reaction with an average of 29 mols of propylene oxide and 6 mols of ethylene oxide on each end of the silicone polymer. Finally, the polymer is neutralized with Tromethamine.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"2e73345f-ff42-4ade-82f8-a5c1932c0bda","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYSILICONE-34"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polysilicone-34 is a complex polymeric salt made by reacting Acrylates/C10-30 Alkyl Acrylate Crosspolymer with a silicone polymer that is prepared by reacting Bis-Hydroxypropyl Dimethicone with 2,3-epoxypropylamine followed by reaction with an average of 29 mols of propylene oxide and 6 mols of ethylene oxide on each end of the silicone polymer. Finally, the polymer is neutralized with Tromethamine."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["DAD6CBEB0BCA6184AFD83F01411270C9"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":