  (94953, '995ca83f-d18f-4e3a-9fe3-d4edd6eab3ab'::uuid, 'SH-POLYPEPTIDE-98 HEXAPEPTIDE-40', 'SH-POLYPEPTIDE-98 HEXAPEPTIDE-40', NULL, NULL, NULL, 'sh-Polypeptide-98 Hexapeptide-40 is a single chain fusion peptide, produced by fermentation in HeLa cells. The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-98 and Decapeptide-40. The fusion peptide contains 485 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"995ca83f-d18f-4e3a-9fe3-d4edd6eab3ab","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.3742867,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-98 HEXAPEPTIDE-40"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":["https://ec.europa.eu/health/sites/health/files/scientific_committees/consumer_safety/docs/sccs_o_159.pdf"],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"language":["en"],"chemicalDescription":["sh-Polypeptide-98 Hexapeptide-40 is a single chain fusion peptide, produced by fermentation in HeLa cells. The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-98 and Decapeptide-40. The fusion peptide contains 485 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["0B52609C1E3464F7728BE54893E342C3"],"cosmeticRestriction":[],"ecNo":[],"maximumCo