  (94970, '98f01e41-18bf-41f6-8365-ae92ebaf1f84'::uuid, 'SR-RAINBOW TROUT OLIGOPEPTIDE-1 SH-POLYPEPTIDE-1', 'SR-RAINBOW TROUT OLIGOPEPTIDE-1 SH-POLYPEPTIDE-1', NULL, NULL, NULL, 'sr-Rainbow Trout Oligopeptide-1 sh-Polypeptide-1 is a single chain fusion peptide, produced by fermentation in  E. coli. The starting gene is synthesized by the fusion of the gene from sr-Rainbow Trout Oligopeptide-1 and sh-Polypeptide-1. The fusion peptide contains 160 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"98f01e41-18bf-41f6-8365-ae92ebaf1f84","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SR-RAINBOW TROUT OLIGOPEPTIDE-1 SH-POLYPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-Rainbow Trout Oligopeptide-1 sh-Polypeptide-1 is a single chain fusion peptide, produced by fermentation in  E. coli. The starting gene is synthesized by the fusion of the gene from sr-Rainbow Trout Oligopeptide-1 and sh-Polypeptide-1. The fusion peptide contains 160 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["8DC8AD36FCD1419B20A5D38DDEF343EE"],"cosmeticRestriction":[],"