  (95221, '962b4641-1f4b-47a9-8ef4-536e5e268665'::uuid, 'S-CLOSTRIDIUM BOTULINUM DECAPEPTIDE-1', 'S-CLOSTRIDIUM BOTULINUM DECAPEPTIDE-1', NULL, NULL, NULL, 's-Clostridium Botulinum Decapeptide-1 is a single chain peptide produced synthetically to be identical to a portion of the protein, Botulinum Neurotoxin Type A, which is found in the bacteria, Clostridium botulinum. It contains 10 amino acids consisting of cysteine, glutamic acid, glycine, histidine, lysine, phenylalanine, and serine. The parent protein contains a maximum of 1296 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"962b4641-1f4b-47a9-8ef4-536e5e268665","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-CLOSTRIDIUM BOTULINUM DECAPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Clostridium Botulinum Decapeptide-1 is a single chain peptide produced synthetically to be identical to a portion of the protein, Botulinum Neurotoxin Type A, which is found in the bacteria, Clostridium botulinum. It contains 10 amino acids consisting of cysteine, glutamic acid, glycine, histidine, lysine, phenylalanine, and serine. The parent protein contains a maximum of 1296 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["571B3CAE6756134B06A495462EB0B1F2"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["S-CLOSTRIDIUM BOTULINUM DECAPEPTIDE-1"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["95221"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN PROTECTING"],"esDA_IngestDate":["2023-05-22T16:47:02.638+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:47:02.606+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"962b4641-1f4b-47a9-8ef4-536e5e268665. Available at: urn:test"}'::jsonb),
