  (95400, '101cd04a-ff42-41ea-8879-b8e24a02f81b'::uuid, 'S-VIPER CYSTEINE-RICH VENOM PROTEIN', 'S-VIPER CYSTEINE-RICH VENOM PROTEIN', NULL, NULL, NULL, 's-Viper Cysteine-Rich Venom Protein is a single chain protein produced synthetically to be identical to Cysteine-rich venom protein which is found in the viper, Daboia russelii. The protein contains 10 amino acids which may contain disulfide bonds and/or glycosylation and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"101cd04a-ff42-41ea-8879-b8e24a02f81b","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-VIPER CYSTEINE-RICH VENOM PROTEIN"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Viper Cysteine-Rich Venom Protein is a single chain protein produced synthetically to be identical to Cysteine-rich venom protein which is found in the viper, Daboia russelii. The protein contains 10 amino acids which may contain disulfide bonds and/or glycosylation and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["E11FFAF40E9F038C7A3DEC5B7722FE44"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["S-VIPER CYSTEINE-RICH VENOM PROTEIN"],"esST_FileName":["file.txt"],"c