  (95401, '36a36199-f922-400d-8ed0-887efce91488'::uuid, 'ENTEROCOCCUS FAECIUM/SAURURUS CHINENSIS EXTRACT FERMENT FILTRATE', 'ENTEROCOCCUS FAECIUM/SAURURUS CHINENSIS EXTRACT FERMENT FILTRATE', NULL, NULL, NULL, 'Enterococcus Faecium/Saururus Chinensis Extract Ferment Filtrate is a filtrate of the product obtained by the fermentation of Saururus Chinensis Extract by the microorganism, Enterococcus faecium, Saururaceae.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"36a36199-f922-400d-8ed0-887efce91488","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["ENTEROCOCCUS FAECIUM/SAURURUS CHINENSIS EXTRACT FERMENT FILTRATE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Enterococcus Faecium/Saururus Chinensis Extract Ferment Filtrate is a filtrate of the product obtained by the fermentation of Saururus Chinensis Extract by the microorganism, Enterococcus faecium, Saururaceae."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["1AD6739BE55E8487DBA334C4E7F7327C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["ENTEROCOCCUS FAECIUM/SAURURUS CHINENSIS EXTRACT FERMENT FILTRATE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["95401"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":