  (95402, '4ac6f819-3d9e-40d6-aa30-fa2120474c9e'::uuid, 'S-CENTIPEDE DECAPEPTIDE-1', 'S-CENTIPEDE DECAPEPTIDE-1', NULL, NULL, 'Kappa-SLPTX-Ssm2e', 's-Centipede Decapeptide-1 is a single chain protein synthetically produced based on a sequence from Kappa-scoloptoxin-Ssm2e which is found in the centipede,  Scolopendra mutilans. Kappa-scoloptoxin-Ssm2e contains 98 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"4ac6f819-3d9e-40d6-aa30-fa2120474c9e","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-CENTIPEDE DECAPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Kappa-SLPTX-Ssm2e"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Centipede Decapeptide-1 is a single chain protein synthetically produced based on a sequence from Kappa-scoloptoxin-Ssm2e which is found in the centipede,  Scolopendra mutilans. Kappa-scoloptoxin-Ssm2e contains 98 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["491593C782BAB7C3C45D16E04CC56C19"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["S-CENTIPEDE DECAPEPTIDE-1"],"esST_FileName":["file.tx