  (95413, '34ae71a3-c9c9-4c29-9c28-075c4ca78ea7'::uuid, 'NICOTIANA BENTHAMIANA SH-POLYPEPTIDE-15 HEXAPEPTIDE-40', 'NICOTIANA BENTHAMIANA SH-POLYPEPTIDE-15 HEXAPEPTIDE-40', NULL, NULL, NULL, 'Nicotiana Benthamiana sh-Polypeptide-15 Hexapeptide-40 is a fusion peptide of Hexapeptide-40 with a single chain recombinant human peptide produced by  Nicotiana benthamiana  after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Tissue Inhibitor of Metalloproteinases-2 which contains a maximum of 220 amino acids. The fusion peptide contains 200 amino acids and may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"34ae71a3-c9c9-4c29-9c28-075c4ca78ea7","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["NICOTIANA BENTHAMIANA SH-POLYPEPTIDE-15 HEXAPEPTIDE-40"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Nicotiana Benthamiana sh-Polypeptide-15 Hexapeptide-40 is a fusion peptide of Hexapeptide-40 with a single chain recombinant human peptide produced by  Nicotiana benthamiana  after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Tissue Inhibitor of Metalloproteinases-2 which contains a maximum of 220 amino acids. The fusion peptide contains 200 amino acids and may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["77C8DD408802576BB5941C9632F9D075"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["NICOTIANA BENTHAMIANA SH-POLYPEPTIDE-15 HEXAPEPTIDE-40"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["95413"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING"],"esDA_IngestDate":["2023-05-22T16:46:14.887+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:46:14.863+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"34ae71a3-c9c9-4c29-9c28-075c4ca78ea7. Available at: urn:test"}'::jsonb),
