  (95503, '66e5b508-f8d0-4079-b13e-35d6847c010e'::uuid, 'SH-POLYPEPTIDE-101', 'SH-POLYPEPTIDE-101', NULL, NULL, NULL, 'sh-Polypeptide-101 is a single chain recombinant human peptide, produced by fermentation in  E. coli. The starting gene is a synthesized copy of the human gene which codes for Adiponectin used such or adapted to the production host. It contains a maximum of 244 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"66e5b508-f8d0-4079-b13e-35d6847c010e","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-101"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-101 is a single chain recombinant human peptide, produced by fermentation in  E. coli. The starting gene is a synthesized copy of the human gene which codes for Adiponectin used such or adapted to the production host. It contains a maximum of 244 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["1489A665DDC84D460A99DE9A7FB33E95"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":[