  (95683, '185e5433-64da-43f4-a050-1f0d25f05080'::uuid, 'EPOXY RESIN-2', 'EPOXY RESIN-2', NULL, NULL, NULL, 'Epoxy Resin-2 is a copolymer formed by first reacting bis(hexamethylene)triamine with 3 moles of glycidyl neodecanoate. This compound is further reacted with isopropylidenebisphenol diglycidyl ether, Dimethylaminopropylamine and Diethanolamine. The resulting polymer is capped with Tall Oil Acid, partially neutralized with Acetic Acid, and dispersed into water.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"185e5433-64da-43f4-a050-1f0d25f05080","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["EPOXY RESIN-2"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Epoxy Resin-2 is a copolymer formed by first reacting bis(hexamethylene)triamine with 3 moles of glycidyl neodecanoate. This compound is further reacted with isopropylidenebisphenol diglycidyl ether, Dimethylaminopropylamine and Diethanolamine. The resulting polymer is capped with Tall Oil Acid, partially neutralized with Acetic Acid, and dispersed into water."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["84ED04477CE2B17C653295926E7A0B54"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["EPOXY RESIN-2"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["95683"],"an