  (95702, 'b824437e-980c-491f-a6ec-4cf51aa7c653'::uuid, 'SH-POLYPEPTIDE-107', 'SH-POLYPEPTIDE-107', NULL, NULL, NULL, 'sh-Polypeptide-107 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is a synthesized copy of the human gene which codes for Mitochondrial Peptide Methionine Sulfoxide Reductase used as such or adapted to the production host. It contains a maximum of 235 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b824437e-980c-491f-a6ec-4cf51aa7c653","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-107"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-107 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is a synthesized copy of the human gene which codes for Mitochondrial Peptide Methionine Sulfoxide Reductase used as such or adapted to the production host. It contains a maximum of 235 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["0EB13DF2D31E5DAAD15F12C6D1FC4D40"],"cosmeticRestriction":[],"ecNo"