  (95712, 'f21b6b0c-7ef5-4887-871d-533c480b6357'::uuid, 'R-(METHIONYL TRIPEPTIDE-46 HEXAPEPTIDE-40 TETRAPEPTIDE-66 SYNECHOCOCCUS POLYPEPTIDE-1)', 'R-(METHIONYL TRIPEPTIDE-46 HEXAPEPTIDE-40 TETRAPEPTIDE-66 SYNECHOCOCCUS POLYPEPTIDE-1)', NULL, NULL, NULL, 'r-(Methionyl Tripeptide-46 Hexapeptide-40 Tetrapeptide-66 Synechococcus Polypeptide-1) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the genes from Tripeptide-46, Hexapeptide-40, Tetrapeptide-66 and r-Synechococcus Polypeptide-1 with the initiation codon for methionine. The fusion peptide contains 178 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"f21b6b0c-7ef5-4887-871d-533c480b6357","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["R-(METHIONYL TRIPEPTIDE-46 HEXAPEPTIDE-40 TETRAPEPTIDE-66 SYNECHOCOCCUS POLYPEPTIDE-1)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["r-(Methionyl Tripeptide-46 Hexapeptide-40 Tetrapeptide-66 Synechococcus Polypeptide-1) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the genes from Tripeptide-46, Hexapeptide-40, Tetrapeptide-66 and r-Synechococcus Polypeptide-1 with the initiation codon for methionine. The fusion peptide contains 178 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["6629FFFDBE4B88DB134567EEF36EE258"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["R-(METHIONYL TRIPEPTIDE-46 HEXAPEPTIDE-40 TETRAPEPTIDE-66 SYNECHOCOCCUS POLYPEPTIDE-1)"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["95712"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIMICROBIAL","ANTIOXIDANT","ASTRINGENT","COLORANT","HUMECTANT","SKIN CONDITIONING","UV FILTER"],"esDA_IngestDate":["2023-05-23T07:46:19.027+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:46:19.002+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"f21b6b0c-7ef5-4887-871d-533c480b6357. Available at: urn:test"}'::jsonb),
