  (95746, 'f478f48e-ab22-4a4d-b0c8-4d37f5746466'::uuid, 'AMINOPROPYL MAGNESIUM POLYSILSESQUIOXANE CHLORIDE', 'AMINOPROPYL MAGNESIUM POLYSILSESQUIOXANE CHLORIDE', NULL, NULL, NULL, 'Aminopropyl Magnesium Polysilsesquioxane Chloride is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, each silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2, where R represents the aminopropyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group. Aminopropyl Magnesium Polysilsesquioxane Chloride is prepared by the hydrolysis and condensation of 3-aminopropyltriethoxysilane, and reaction with magnesium chloride', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"f478f48e-ab22-4a4d-b0c8-4d37f5746466","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["AMINOPROPYL MAGNESIUM POLYSILSESQUIOXANE CHLORIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Aminopropyl Magnesium Polysilsesquioxane Chloride is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, each silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2, where R represents the aminopropyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group. Aminopropyl Magnesium Polysilsesquioxane Chloride is prepared by the hydrolysis and condensation of 3-aminopropyltriethoxysilane, and reaction with magnesium chloride"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["8D0FCB5DBCB95EA5F1235A0A1BA8766E"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["AMINOPROPYL MAGNESIUM POLYSILSESQUIOXANE CHLORIDE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["95746"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIMICROBIAL","HUMECTANT","SKIN CONDITIONING"],"esDA_IngestDate":["2023-05-23T07:46:41.289+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:46:41.263+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"f478f48e-ab22-4a4d-b0c8-4d37f5746466. Available at: urn:test"}'::jsonb),
