  (95774, '23ac6214-f698-41d0-a975-560746f7e377'::uuid, 'BIS-ETHYLHEXYL POLY(CAPROLACTONE/PENTAERYTHRITOL)/IPDI COPOLYMER SUCCINATE', 'BIS-ETHYLHEXYL POLY(CAPROLACTONE/PENTAERYTHRITOL)/IPDI COPOLYMER SUCCINATE', NULL, NULL, NULL, 'Bis-Ethylhexyl Poly(Caprolactone/Pentaerythritol)/IPDI Copolymer Succinate is a urethane copolymer made by a two-step synthesis. First, a polyester made by polymerizing Epsilon-Caprolactone with Pentaerythritol is reacted with Isophorone Diisocyanate.  2-ethyl hexanol is used as an end-capper for the urethane copolymer. In the second step, the urethane copolymer is esterified with succinic anhydride.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"23ac6214-f698-41d0-a975-560746f7e377","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-ETHYLHEXYL POLY(CAPROLACTONE/PENTAERYTHRITOL)/IPDI COPOLYMER SUCCINATE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-Ethylhexyl Poly(Caprolactone/Pentaerythritol)/IPDI Copolymer Succinate is a urethane copolymer made by a two-step synthesis. First, a polyester made by polymerizing Epsilon-Caprolactone with Pentaerythritol is reacted with Isophorone Diisocyanate.  2-ethyl hexanol is used as an end-capper for the urethane copolymer. In the second step, the urethane copolymer is esterified with succinic anhydride."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"r