  (95882, 'e050720f-f476-43fc-a640-87815cd9c377'::uuid, 'S-BOVINE OLIGOPEPTIDE-1', 'S-BOVINE OLIGOPEPTIDE-1', NULL, NULL, NULL, 's-Bovine Oligopeptide-1 is a single chain peptide synthetically produced based on a 18 amino acid sequence from cow Lactoferrin. The parent protein contains a maximum of 690 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"e050720f-f476-43fc-a640-87815cd9c377","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-BOVINE OLIGOPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Bovine Oligopeptide-1 is a single chain peptide synthetically produced based on a 18 amino acid sequence from cow Lactoferrin. The parent protein contains a maximum of 690 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["748389313C89A03C7E76226A6196A9ED"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["S-BOVINE OLIGOPEPTIDE-1"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["95882"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"o