  (95901, 'b080079a-0c8e-488a-a30f-257aadff4aee'::uuid, 'R-(SH-POLYPEPTIDE-92 OLIGOPEPTIDE-159 SH-OLIGOPEPTIDE-1)', 'R-(SH-POLYPEPTIDE-92 OLIGOPEPTIDE-159 SH-OLIGOPEPTIDE-1)', NULL, NULL, NULL, 'r-(sh-Polypeptide-92 Oligopeptide-159 sh-Oligopeptide-1) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the genes encoding for sh-Polypeptide-92, Oligopeptide-159 and sh-Oligopeptide-1. The fusion peptide contains 161 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b080079a-0c8e-488a-a30f-257aadff4aee","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["R-(SH-POLYPEPTIDE-92 OLIGOPEPTIDE-159 SH-OLIGOPEPTIDE-1)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["r-(sh-Polypeptide-92 Oligopeptide-159 sh-Oligopeptide-1) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the genes encoding for sh-Polypeptide-92, Oligopeptide-159 and sh-Oligopeptide-1. The fusion peptide contains 161 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"