  (95999, '4d36a041-81bb-4329-8413-84a24d6d767f'::uuid, 'BIS-METHOXY PEG-114 POLYCAPROLACTONE DIOL/IPDI COPOLYMER', 'BIS-METHOXY PEG-114 POLYCAPROLACTONE DIOL/IPDI COPOLYMER', NULL, NULL, NULL, 'Bis-Methoxy PEG-114 Polycaprolactone Diol/IPDI Copolymer is a polymer made by the reaction of Isophorone Diisocyanate with a polyester pre-polymer formed by condensing Epsilon-Caprolactone with Diethylene Glycol, and capping the resulting polymer with methoxy PEG-114.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"4d36a041-81bb-4329-8413-84a24d6d767f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":7.2819624,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-METHOXY PEG-114 POLYCAPROLACTONE DIOL/IPDI COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-Methoxy PEG-114 Polycaprolactone Diol/IPDI Copolymer is a polymer made by the reaction of Isophorone Diisocyanate with a polyester pre-polymer formed by condensing Epsilon-Caprolactone with Diethylene Glycol, and capping the resulting polymer with methoxy PEG-114."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["32CCB7AA6D594F5D674743DF52A5BF19"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["BIS-METHOXY PEG-114 POLYCAPROLACTONE DIOL/IPDI COPOLYMER"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["95999"],"annexNo":[],"produ