  (96099, '13bffed0-2e02-4dfb-be9e-f2e81d35d2d6'::uuid, 'R-CHAETOCEROS NEOGRACILE POLYPEPTIDE-1', 'R-CHAETOCEROS NEOGRACILE POLYPEPTIDE-1', NULL, NULL, NULL, 'R-Chaetoceros Neogracile Polypeptide-1 is a single chain recombinant protein produced by fermentation in E. coli. The starting gene, which codes for Antifreeze protein, is directly isolated from Chaetoceros neogracile. The protein contains a maximum of 282 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"13bffed0-2e02-4dfb-be9e-f2e81d35d2d6","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["R-CHAETOCEROS NEOGRACILE POLYPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["R-Chaetoceros Neogracile Polypeptide-1 is a single chain recombinant protein produced by fermentation in E. coli. The starting gene, which codes for Antifreeze protein, is directly isolated from Chaetoceros neogracile. The protein contains a maximum of 282 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["E19BE7BCB1AE6C2D92885BCA5C1ACDB2"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient"