  (96146, 'f204d98b-c88b-4e74-81a0-dffe49621bd7'::uuid, 'POLYURETHANE-84', 'POLYURETHANE-84', NULL, NULL, 'Propanoic acid, 3-hydroxy-2-(hydroxymethyl)-2-methyl-, polymer with 1,4-cyclohexanedimethanol, dimethyl carbonate, 1,6-hexanediol and 1,1''-methylenebis[4-isocyanatocyclohexane], compd. with N,N-diethylethanamine', 'Polyurethane-84 is a urethane polymer prepared by a multi-step process. First, a polyester is made by condensing Hexanediol with Dimethyl Carbonate. The polyester is then reacted with Dimethylolpropionic Acid, Cyclohexane Dimethanol, and Saturated Methylene Diphenyl Diisocyanate to form a polyurethane. The polyurethane is neutralized with Triethylamine to make it water-dispersible, then chain extended with hydrazine and Diethylenetriamine.', NULL, NULL, 'II/201', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"f204d98b-c88b-4e74-81a0-dffe49621bd7","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":7.2819624,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-84"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Propanoic acid, 3-hydroxy-2-(hydroxymethyl)-2-methyl-, polymer with 1,4-cyclohexanedimethanol, dimethyl carbonate, 1,6-hexanediol and 1,1''-methylenebis[4-isocyanatocyclohexane], compd. with N,N-diethylethanamine"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-84 is a urethane polymer prepared by a multi-step process. First, a polyester is made by condensing Hexanediol with Dimethyl Carbonate. The polyester is then reacted with Dimethylolpropionic Acid, Cyclohexane Dimethanol, and Saturated Methylene Diphenyl Diisocyanate to form a polyurethane. The polyurethane is neutralized with Triethylamine to make it water-dispersible, then chain extended with hydrazine and Diethylenetriamine."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["431A32AEF6C5C4CE6C61E347BD84C7CE"],"cosmeticRestriction":["II/201"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-84"],"esST_FileName":["file.txt"],"casNo":["1436463-63-6"],"substanceId":["96146"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["NAIL CONDITIONING"],"esDA_IngestDate":["2023-05-23T07:47:32.070+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:47:32.043+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"f204d98b-c88b-4e74-81a0-dffe49621bd7. Available at: urn:test"}'::jsonb),
