  (96166, '6f46ac9c-e398-46da-bdb2-2446dd0560fe'::uuid, 'SH-POLYPEPTIDE-109', 'SH-POLYPEPTIDE-109', NULL, NULL, NULL, 'sh-Polypeptide-109 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is a synthesized copy of the human gene which codes for Human Sonic Hedgehog Protein used as such or adapted to the production host. It contains a maximum of 462 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"6f46ac9c-e398-46da-bdb2-2446dd0560fe","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.861625,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-109"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-109 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is a synthesized copy of the human gene which codes for Human Sonic Hedgehog Protein used as such or adapted to the production host. It contains a maximum of 462 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["050336BC7AE68B674747DAE4D68A9B77"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredie