  (96232, '5004f679-9d06-4485-a8fc-5cbded05ab29'::uuid, 'S-HIV-1 OLIGOPEPTIDE-1', 'S-HIV-1 OLIGOPEPTIDE-1', NULL, NULL, NULL, 's-HIV-1 Oligopeptide-1 is a single chain protein containing 38 amino acids. It is synthetically produced based on the sequence for Protein TAT which is found in the pathogenic virus, Human Immunodeficiency Virus-1 (HIV-1). It contains 111 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, NULL, NULL, '{"apiVersion":"2.151","reference":"5004f679-9d06-4485-a8fc-5cbded05ab29","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-HIV-1 OLIGOPEPTIDE-1"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-HIV-1 Oligopeptide-1 is a single chain protein containing 38 amino acids. It is synthetically produced based on the sequence for Protein TAT which is found in the pathogenic virus, Human Immunodeficiency Virus-1 (HIV-1). It contains 111 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["5004f679-9d06-4485-a8fc-5cbded05ab29"],"reference":["B323AA05E8623E12BE4B71CEBB6F9665"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["S-HIV-1 OLIGOPEPTIDE-1"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96232"],"productTypeBodyParts":[],"