  (96279, '47882172-e3c6-4e3e-b3b7-1263daf24814'::uuid, 'SILKWORM SH-POLYPEPTIDE-47', 'Silkworm sh-Polypeptide-47', NULL, NULL, NULL, 'Silkworm sh-Polypeptide-47 is a single chain recombinant human peptide, produced by silkworm after after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Collagen Alpha 1. It contains a maximum of 1464 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"47882172-e3c6-4e3e-b3b7-1263daf24814","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.3742867,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Silkworm sh-Polypeptide-47"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Silkworm sh-Polypeptide-47 is a single chain recombinant human peptide, produced by silkworm after after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Collagen Alpha 1. It contains a maximum of 1464 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["579755062CD8656359EE0636D874B825"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SILKWORM SH-POLYPEPTIDE-47"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96279"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HUMECTANT","SKIN CONDITIONING"],"esDA_IngestDate":["2023-05-22T15:47:56.953+0200"],"currentVersion":["1"],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T15:47:56.909+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"47882172-e3c6-4e3e-b3b7-1263daf24814. Available at: urn:test"}'::jsonb),
