  (96302, '89bc2485-8c47-4d27-93f4-e9700470cad3'::uuid, 'NICOTIANA BENTHAMIANA R-(S-CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 S-SPIDER OLIGOPEPTIDE-1 SH-OLIGOPEPTIDE-1)', 'NICOTIANA BENTHAMIANA R-(S-CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 S-SPIDER OLIGOPEPTIDE-1 SH-OLIGOPEPTIDE-1)', NULL, NULL, NULL, 'Nicotiana Benthamiana r-(s-Clostridium Botulinum Polypeptide-1 s-Spider Oligopeptide-1 sh-Oligopeptide-1) is a single chain recombinant protein produced by Nicotiana benthamiana after using either a transient expression system or transgenesis (stable insertion of a copy of the synthetic gene into its DNA). The starting gene is synthesized by the fusion of the genes from s-Clostridium Botulinum Polypeptide-1, s-Spider Oligopeptide-1, and sh-Oligopeptide-1. The peptide contains a maximum of 548 amino acids which may contain disulfide bonds and/or glycosylation. The fusion peptide consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"89bc2485-8c47-4d27-93f4-e9700470cad3","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["NICOTIANA BENTHAMIANA R-(S-CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 S-SPIDER OLIGOPEPTIDE-1 SH-OLIGOPEPTIDE-1)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Nicotiana Benthamiana r-(s-Clostridium Botulinum Polypeptide-1 s-Spider Oligopeptide-1 sh-Oligopeptide-1) is a single chain recombinant protein produced by Nicotiana benthamiana after using either a transient expression system or transgenesis (stable insertion of a copy of the synthetic gene into its DNA). The starting gene is synthesized by the fusion of the genes from s-Clostridium Botulinum Polypeptide-1, s-Spider Oligopeptide-1, and sh-Oligopeptide-1. The peptide contains a maximum of 548 amino acids which may contain disulfide bonds and/or glycosylation. The fusion peptide consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["22FCCF9B846938E660C795B806546024"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["NICOTIANA BENTHAMIANA R-(S-CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 S-SPIDER OLIGOPEPTIDE-1 SH-OLIGOPEPTIDE-1)"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96302"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING"],"esDA_IngestDate":["2023-05-23T07:47:19.004+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:47:18.974+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"89bc2485-8c47-4d27-93f4-e9700470cad3. Available at: urn:test"}'::jsonb),
