  (96314, '2de588de-7b90-4c3a-ab32-e3a13ba3c543'::uuid, 'SH-OLIGOPEPTIDE-90 SP', 'SH-OLIGOPEPTIDE-90 SP', NULL, NULL, NULL, 'sh-Oligopeptide-90 SP is a 11 amino acid protein fragment produced synthetically to be identical to a portion of the human protein, Keratin-associated protein 1-1. The parent protein contains a maximum of 177 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"2de588de-7b90-4c3a-ab32-e3a13ba3c543","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-OLIGOPEPTIDE-90 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Oligopeptide-90 SP is a 11 amino acid protein fragment produced synthetically to be identical to a portion of the human protein, Keratin-associated protein 1-1. The parent protein contains a maximum of 177 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["D284F32FEFCDF4A348C92182C5E9A4BE"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SH-OLIGOPEPTIDE-90 SP"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96314"],"annexNo