  (96321, 'eb617242-36ef-439d-abf0-92bc835b6501'::uuid, 'SH-HEPTAPEPTIDE-4 SP TRIFLUOROACETATE', 'SH-HEPTAPEPTIDE-4 SP TRIFLUOROACETATE', NULL, NULL, NULL, 'sh-Heptapeptide-4 SP Trifluoroacetate is the trifluoroacetate salt of a single chain human peptide produced synthetically to be identical to a portion of the protein, Osteopontin and contains 7 amino acids consisting of arginine, glycine, leucine, serine, tyrosine and valine. Osteopontin contains a maximum of 314 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"eb617242-36ef-439d-abf0-92bc835b6501","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.3742867,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-HEPTAPEPTIDE-4 SP TRIFLUOROACETATE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Heptapeptide-4 SP Trifluoroacetate is the trifluoroacetate salt of a single chain human peptide produced synthetically to be identical to a portion of the protein, Osteopontin and contains 7 amino acids consisting of arginine, glycine, leucine, serine, tyrosine and valine. Osteopontin contains a maximum of 314 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"re