  (96390, '644ec3ef-3880-44be-a362-33eaba599e17'::uuid, 'POLYURETHANE-85', 'POLYURETHANE-85', NULL, NULL, NULL, 'Polyurethane-85 is a urethane polymer formed by reacting poly(1,4-butanediol)-28, poly(1,4-butanediol)-41 and isopropylidendicyclohexanol with Isophorone Diisocyanate. The polymer is capped with 2-Hydroxyethyl Acrylate.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"644ec3ef-3880-44be-a362-33eaba599e17","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-85"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-85 is a urethane polymer formed by reacting poly(1,4-butanediol)-28, poly(1,4-butanediol)-41 and isopropylidendicyclohexanol with Isophorone Diisocyanate. The polymer is capped with 2-Hydroxyethyl Acrylate."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["63C548F22DF1D6555197A5E7D01D2746"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-85"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96390"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["BINDING"],"esDA_IngestDate":["2023-05-23T07:53:00.435+0200"],"currentVersion":[],"corporate-search-version":["102"],"url"