  (96391, '8eb5a406-efe3-495a-8be2-95f558db32f3'::uuid, 'POLYURETHANE-86', 'POLYURETHANE-86', NULL, NULL, NULL, 'Polyurethane-86 is a urethane polymer formed by a multi-step process. First, a polyester is made by condensing Ethylene Carbonate and Hexanediol. This polyester and 1,5-Pentanediol are reacted with Isophorone Diisocyanate. The polymer is capped with HEMA.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"8eb5a406-efe3-495a-8be2-95f558db32f3","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-86"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-86 is a urethane polymer formed by a multi-step process. First, a polyester is made by condensing Ethylene Carbonate and Hexanediol. This polyester and 1,5-Pentanediol are reacted with Isophorone Diisocyanate. The polymer is capped with HEMA."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["8A551A7C800ED27F6F630F340732C1B1"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-86"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96391"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["BINDING"],"esDA_IngestDate":["2023-05-23T07:53:00