  (96392, '7c5a6e0c-77f5-49d2-acef-533da6d19211'::uuid, 'BIS-HEA SMDI/PPG-6 COPOLYMER', 'BIS-HEA SMDI/PPG-6 COPOLYMER', NULL, NULL, NULL, 'Bis-HEA SMDI/PPG-6 Copolymer is the polymer made by the reaction of Saturated Methylene Diphenyl Diisocyanate (SMDI) and PPG-6, end-capped with 2-Hydroxyethyl Acrylate.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"7c5a6e0c-77f5-49d2-acef-533da6d19211","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-HEA SMDI/PPG-6 COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-HEA SMDI/PPG-6 Copolymer is the polymer made by the reaction of Saturated Methylene Diphenyl Diisocyanate (SMDI) and PPG-6, end-capped with 2-Hydroxyethyl Acrylate."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["D0CEE7D3FA01972AFE102A151A9BA4DF"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["BIS-HEA SMDI/PPG-6 COPOLYMER"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96392"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["BINDING","NAIL CONDITIONING"],"esDA_IngestDate":["2023-05-23T07:53:00.876+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn