  (96394, 'e1f1d1df-449f-4f4c-8a0a-50414d74c8c3'::uuid, 'POLYURETHANE-87', 'POLYURETHANE-87', NULL, NULL, NULL, 'Polyurethane-87 is a urethane polymer formed by a multi-step process. First, a polyester is made by condensing Adipic Acid and 3-methyl-1,5-pentanediol, which is subsequently reacted with PEG-45, Glycol and Methylene Diphenyl Diisocyanate. The resulting polymer is capped with n-Butyl Alcohol.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"e1f1d1df-449f-4f4c-8a0a-50414d74c8c3","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-87"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-87 is a urethane polymer formed by a multi-step process. First, a polyester is made by condensing Adipic Acid and 3-methyl-1,5-pentanediol, which is subsequently reacted with PEG-45, Glycol and Methylene Diphenyl Diisocyanate. The resulting polymer is capped with n-Butyl Alcohol."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["4E56D342A65AF7821F850504971A36A7"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-87"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96394"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformatio