  (96397, '1a9f62f4-0466-42cc-986e-c13135b3af39'::uuid, 'BIS-HEMA POLY(PENTYLENE/HEXAMETHYLENE CARBONATE)/IPDI COPOLYMER', 'BIS-HEMA POLY(PENTYLENE/HEXAMETHYLENE CARBONATE)/IPDI COPOLYMER', NULL, NULL, NULL, 'Bis-HEMA Poly(Pentylene/Hexamethylene Carbonate)/IPDI Copolymer is a urethane polymer formed by a multi-step process. First, a prepolymer is made by condensing 1,5-Pentanediol, Hexanediol and Dimethyl Carbonate, which is subsequently reacted with {29375; Isophorone Diisocyanate}. The resulting polymer is end-capped with HEMA.', NULL, '-', NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"1a9f62f4-0466-42cc-986e-c13135b3af39","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-HEMA POLY(PENTYLENE/HEXAMETHYLENE CARBONATE)/IPDI COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-HEMA Poly(Pentylene/Hexamethylene Carbonate)/IPDI Copolymer is a urethane polymer formed by a multi-step process. First, a prepolymer is made by condensing 1,5-Pentanediol, Hexanediol and Dimethyl Carbonate, which is subsequently reacted with {29375; Isophorone Diisocyanate}. The resulting polymer is end-capped with HEMA."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["3DBD4D0BC0156983D28A17A58D95042E"],"cosmeticRestriction":[],"ecNo":["-"],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["B