  (96398, '867393fc-5b9a-42ff-a806-17532f16daaf'::uuid, 'BIS-HEMA POLY(CAPROLACTONE/PENTAERYTHRITOL)/IPDI COPOLYMER SUCCINATE', 'BIS-HEMA POLY(CAPROLACTONE/PENTAERYTHRITOL)/IPDI COPOLYMER SUCCINATE', NULL, NULL, NULL, 'Bis-HEMA Poly(Caprolactone/Pentaerythritol)/IPDI Copolymer Succinate is a urethane polymer formed by a multi-step process. First, a polyester is made by reacting Epsilon-Caprolactone with Pentaerythritol, which is subsequently reacted with Isophorone Diisocyanate. The resulting polymer is end-capped with HEMA and esterified with Succinic Anhydride.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"867393fc-5b9a-42ff-a806-17532f16daaf","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-HEMA POLY(CAPROLACTONE/PENTAERYTHRITOL)/IPDI COPOLYMER SUCCINATE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-HEMA Poly(Caprolactone/Pentaerythritol)/IPDI Copolymer Succinate is a urethane polymer formed by a multi-step process. First, a polyester is made by reacting Epsilon-Caprolactone with Pentaerythritol, which is subsequently reacted with Isophorone Diisocyanate. The resulting polymer is end-capped with HEMA and esterified with Succinic Anhydride."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["9334C93756E82CADDDCB50B68AB6AFCF"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngre