  (96399, '681598d0-19ee-46fa-8650-965efd16ba25'::uuid, 'BIS-ETHYLHEXYL POLY(CAPROLACTONE/PENTAERYTHRITOL)/IPDI COPOLYMER', 'BIS-ETHYLHEXYL POLY(CAPROLACTONE/PENTAERYTHRITOL)/IPDI COPOLYMER', NULL, NULL, NULL, 'Bis-Ethylhexyl Poly(Caprolactone/Pentaerythritol)/IPDI Copolymer is a urethane polymer formed by a multi-step process. First, a polyester is made by the reaction of Epsilon-Caprolactone with Pentaerythritol, which is subsequently reacted with Isophorone Diisocyanate (IPDI). The resulting polymer is end-capped with 2-Ethylhexanol.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"681598d0-19ee-46fa-8650-965efd16ba25","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-ETHYLHEXYL POLY(CAPROLACTONE/PENTAERYTHRITOL)/IPDI COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-Ethylhexyl Poly(Caprolactone/Pentaerythritol)/IPDI Copolymer is a urethane polymer formed by a multi-step process. First, a polyester is made by the reaction of Epsilon-Caprolactone with Pentaerythritol, which is subsequently reacted with Isophorone Diisocyanate (IPDI). The resulting polymer is end-capped with 2-Ethylhexanol."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["2508686E4772A67A40D3D10AB3FE33FF"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inci