  (96405, '14c4c5b1-ae8e-4efc-89a2-1874d9025225'::uuid, 'BIS-HEMA POLY(1,4-BUTANEDIOL)-22/DMPA/NEOPENTYL GLYCOL/IPDI COPOLYMER', 'BIS-HEMA POLY(1,4-BUTANEDIOL)-22/DMPA/NEOPENTYL GLYCOL/IPDI COPOLYMER', NULL, NULL, NULL, 'Bis-HEMA Poly(1,4-Butanediol)-22/DMPA/Neopentyl Glycol/IPDI Copolymer is a urethane polymer formed by the reaction of poly(1,4-butanediol)-22, Dimethylolpropionic Acid, Neopentyl Glycol, and Isophorone Diisocyanate. The polymer is end-capped with HEMA.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"14c4c5b1-ae8e-4efc-89a2-1874d9025225","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-HEMA POLY(1,4-BUTANEDIOL)-22/DMPA/NEOPENTYL GLYCOL/IPDI COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-HEMA Poly(1,4-Butanediol)-22/DMPA/Neopentyl Glycol/IPDI Copolymer is a urethane polymer formed by the reaction of poly(1,4-butanediol)-22, Dimethylolpropionic Acid, Neopentyl Glycol, and Isophorone Diisocyanate. The polymer is end-capped with HEMA."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["F3C2F1673E3DB1A1CB7E4EFBD00CC9F5"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["BIS-HEMA POLY(1,4-BUTANEDIOL)-22/DMPA/NEOPENTYL GLYCOL/IPDI COPOLYMER"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96405"]