  (96406, '4b4ee6f8-cb61-43d3-8436-072438063739'::uuid, 'BIS-ETHYLHEXYL POLY(1,4-BUTANEDIOL)-22/DMPA/NEOPENTYL GLYCOL/IPDI COPOLYMER', 'BIS-ETHYLHEXYL POLY(1,4-BUTANEDIOL)-22/DMPA/NEOPENTYL GLYCOL/IPDI COPOLYMER', NULL, NULL, NULL, 'Bis-Ethylhexyl Poly(1,4-Butanediol)-22/DMPA/Neopentyl Glycol/IPDI Copolymer is a urethane polymer formed by the reaction of poly(1,4-butanediol)-22, Dimethylaminopropylamine (DMAPA), Neopentyl Glycol and Isophorone Diisocyanate (IPDI). The polymer is end-capped with 2-Ethylhexanol.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"4b4ee6f8-cb61-43d3-8436-072438063739","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-ETHYLHEXYL POLY(1,4-BUTANEDIOL)-22/DMPA/NEOPENTYL GLYCOL/IPDI COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-Ethylhexyl Poly(1,4-Butanediol)-22/DMPA/Neopentyl Glycol/IPDI Copolymer is a urethane polymer formed by the reaction of poly(1,4-butanediol)-22, Dimethylaminopropylamine (DMAPA), Neopentyl Glycol and Isophorone Diisocyanate (IPDI). The polymer is end-capped with 2-Ethylhexanol."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["E3541C48982511DA28A59EBCDB39FC5A"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["BIS-ETHYLHEXYL POLY(1,4-BUTANEDIOL)-22/DMPA/NEOPENTYL GLY