  (96409, 'a3712872-cd11-4f5c-bf2f-9920f3458dd3'::uuid, 'POLYURETHANE-90', 'POLYURETHANE-90', NULL, NULL, 'Bis-HEMA Poly(Hexamethylene/Methylpentylene Carbonate)/Neopentyl Glycol/IPDI Copolymer', 'Polyurethane-90 is a urethane polymer formed by a multi-step process. First, a polyester is made by reacting Hexanediol, methylpentanediol and Diethyl Carbonate. A mixture of this polyester and Neopentyl Glycol is reacted with Isophorone Diisocyanate. The resulting polymer is Capped with HEMA.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a3712872-cd11-4f5c-bf2f-9920f3458dd3","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-90"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Bis-HEMA Poly(Hexamethylene/Methylpentylene Carbonate)/Neopentyl Glycol/IPDI Copolymer"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-90 is a urethane polymer formed by a multi-step process. First, a polyester is made by reacting Hexanediol, methylpentanediol and Diethyl Carbonate. A mixture of this polyester and Neopentyl Glycol is reacted with Isophorone Diisocyanate. The resulting polymer is Capped with HEMA."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["9D9FFBC731A107E09281789C8B1510C9"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-90"],"esST_FileName":["file.