  (96410, '61ad7c64-52d9-4bcb-90f3-5fbaaa8ff00b'::uuid, 'POLYACRYLATE-48', 'POLYACRYLATE-48', NULL, NULL, 'Methacryloyloxy Ethyl Betaine/HEA/Stearyl Methacrylate/Perfluorohexylethyl Acrylate Copolymer', 'Polyacrylate-48 is a copolymer of methacryloyloxy ethyl betaine, 2-Hydroxyethyl Acrylate, Stearyl Methacrylate and perfluorohexylethyl acrylate.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"61ad7c64-52d9-4bcb-90f3-5fbaaa8ff00b","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYACRYLATE-48"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Methacryloyloxy Ethyl Betaine/HEA/Stearyl Methacrylate/Perfluorohexylethyl Acrylate Copolymer"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyacrylate-48 is a copolymer of methacryloyloxy ethyl betaine, 2-Hydroxyethyl Acrylate, Stearyl Methacrylate and perfluorohexylethyl acrylate."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["23860131487B07F545788DB314F24655"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYACRYLATE-48"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96410"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN PROTECTING"],"esDA_IngestDate":["2023-05-23T07:54:10.099+0200"],"currentVersion"