  (96411, 'cfb063cc-76c4-4173-8899-e964b0197320'::uuid, 'TRIMETHYLPENTYL/METHOXY PEG-10 PROPYL POLYSILSESQUIOXANE', 'TRIMETHYLPENTYL/METHOXY PEG-10 PROPYL POLYSILSESQUIOXANE', NULL, NULL, NULL, 'Trimethylpentyl/Methoxy PEG-10 Propyl Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, the silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2 where R represents the trimethylpentyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group. Trimethylpentyl/Methoxy PEG-10 Propyl Polysilsesquioxane is prepared by the hydrolysis and condensation of trimethylpentyl trimethoxysilane with Methoxy PEG-10 Propyltrimethoxysilane.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"cfb063cc-76c4-4173-8899-e964b0197320","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.861625,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["TRIMETHYLPENTYL/METHOXY PEG-10 PROPYL POLYSILSESQUIOXANE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Trimethylpentyl/Methoxy PEG-10 Propyl Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. For the oligomers, the silicon atom in the polysilsesquioxane is connected via oxygen atoms to three other silicon atoms and can be represented by the empirical formulation RSiO3/2 where R represents the trimethylpentyl group. For the larger polymeric polysilsesquioxanes, some of the silicon atoms are not connected to other silicon atoms and instead have a silanol (SiOH) group. Trimethylpentyl/Methoxy PEG-10 Propyl Polysilsesquioxane is prepared by the hydrolysis and condensation of trimethylpentyl trimethoxysilane with Methoxy PEG-10 Propyltrimethoxysilane."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["0745E9D7155E651BE1013EFE640F4D3C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["TRIMETHYLPENTYL/METHOXY PEG-10 PROPYL POLYSILSESQUIOXANE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96411"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["NOT REPORTED"],"esDA_IngestDate":["2023-05-23T07:54:10.312+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:54:10.280+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"cfb063cc-76c4-4173-8899-e964b0197320. Available at: urn:test"}'::jsonb),
  (96412, 'a666dc17-7c2b-433a-908c-a5025e2f34cc'::uuid, 'DIOCTYLAMINOETHOXYTRIAZINE AMINOPROPYL SILSESQUIOXANE SILICATE', 'DIOCTYLAMINOETHOXYTRIAZINE AMINOPROPYL SILSESQUIOXANE SILICATE', NULL, NULL, NULL, 'Dioctylaminoethoxytriazine Aminopropyl Silsesquioxane Silicate is a complex inorganic polymer composed of silicate groups (SiO4/2) and silsesquioxane groups (RSiO3/2), where R represents a substituted triazine.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a666dc17-7c2b-433a-908c-a5025e2f34cc","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":7.442367,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["DIOCTYLAMINOETHOXYTRIAZINE AMINOPROPYL SILSESQUIOXANE SILICATE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Dioctylaminoethoxytriazine Aminopropyl Silsesquioxane Silicate is a complex inorganic polymer composed of silicate groups (SiO4/2) and silsesquioxane groups (RSiO3/2), where R represents a substituted triazine."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["2C96C7F2EA79CE00B3A475C4C1A617C1"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["DIOCTYLAMINOETHOXYTRIAZINE AMINOPROPYL SILSESQUIOXANE SILICATE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96412"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"cla