  (96416, '2be95a51-4278-4661-82c2-66e6a1d80c59'::uuid, 'POLYURETHANE-91', 'POLYURETHANE-91', NULL, NULL, NULL, 'Polyurethane-91 is a urethane polymer formed by a multi-step process. First, a polyester is made by reacting Hexanediol with Dimethyl Carbonate. A mixture of this polyester, 3-dimethylamino-1,2-propanediol and 1,4-Butanediol is reacted with Isophorone Diisocyanate. The polymer is neutralized with Lactic Acid.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"2be95a51-4278-4661-82c2-66e6a1d80c59","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-91"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-91 is a urethane polymer formed by a multi-step process. First, a polyester is made by reacting Hexanediol with Dimethyl Carbonate. A mixture of this polyester, 3-dimethylamino-1,2-propanediol and 1,4-Butanediol is reacted with Isophorone Diisocyanate. The polymer is neutralized with Lactic Acid."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["44C07E78F243761007EB380DC2630CF7"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-91"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96416"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulat