  (96696, '8f53f9da-d2ec-4bb4-99bf-917b4eb251e8'::uuid, 'ASPERGILLUS/SACCHAROMYCES/PRUNUS MUME FRUIT/RICE FERMENT LEES EXTRACT', 'ASPERGILLUS/SACCHAROMYCES/PRUNUS MUME FRUIT/RICE FERMENT LEES EXTRACT', NULL, NULL, NULL, 'Aspergillus/Saccharomyces/Prunus Mume Fruit/Rice Ferment Lees Extract is the extract of the residue obtained by the fermentation of Prunus Mume Fruit and the grains of rice, Oryza sativa by the microorganisms Aspergillus and Saccharomyces.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"8f53f9da-d2ec-4bb4-99bf-917b4eb251e8","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["ASPERGILLUS/SACCHAROMYCES/PRUNUS MUME FRUIT/RICE FERMENT LEES EXTRACT"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Aspergillus/Saccharomyces/Prunus Mume Fruit/Rice Ferment Lees Extract is the extract of the residue obtained by the fermentation of Prunus Mume Fruit and the grains of rice, Oryza sativa by the microorganisms Aspergillus and Saccharomyces."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["AA0393483D0563783153C84F586CE728"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["ASPERGILLUS/SACCHAROMYCES/PRUNUS MUME FRUIT/RICE FERMENT LEES EXTRACT"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96696"],"annexNo":[],"productTypeB