  (96704, 'a1c04439-e17e-4965-98a5-409e5e6306fe'::uuid, 'R-(SH-POLYPEPTIDE-111 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-117 SH-POLYPEPTIDE-94 SH-POLYPEPTIDE-95 PENTAPEPTIDE-63 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-6) DIMER', 'R-(SH-POLYPEPTIDE-111 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-117 SH-POLYPEPTIDE-94 SH-POLYPEPTIDE-95 PENTAPEPTIDE-63 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-6) DIMER', NULL, NULL, NULL, 'This peptide is a dimer linked by a disulfide bridge between the cysteines, consisting of a single chain synthetic fusion peptide, produced by fermentation in Chinese Hamster Ovary (CHO). The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-111, Oligopeptide-163, sh-Polypeptide-117, sh-Polypeptide-94, sh-Polypeptide-95, and Pentapeptide-63. This fusion protein binds to Immunoglobulin E (IgE) and Interleukin-10 (IL-10) receptors; and it contains 605 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a1c04439-e17e-4965-98a5-409e5e6306fe","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["R-(SH-POLYPEPTIDE-111 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-117 SH-POLYPEPTIDE-94 SH-POLYPEPTIDE-95 PENTAPEPTIDE-63 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-6) DIMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["This peptide is a dimer linked by a disulfide bridge between the cysteines, consisting of a single chain synthetic fusion peptide, produced by fermentation in Chinese Hamster Ovary (CHO). The starting gene is synthesized by the fusion of the gene from sh-Polypeptide-111, Oligopeptide-163, sh-Polypeptide-117, sh-Polypeptide-94, sh-Polypeptide-95, and Pentapeptide-63. This fusion protein binds to Immunoglobulin E (IgE) and Interleukin-10 (IL-10) receptors; and it contains 605 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["7217E5349F87D0D35F12301901CC64F0"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["R-(SH-POLYPEPTIDE-111 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-117 SH-POLYPEPTIDE-94 SH-POLYPEPTIDE-95 PENTAPEPTIDE-63 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-6) DIMER"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96704"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - EMOLLIENT","SKIN CONDITIONING","SKIN PROTECTING"],"esDA_IngestDate":["2023-05-22T16:51:56.411+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-22T16:51:56.364+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"a1c04439-e17e-4965-98a5-409e5e6306fe. Available at: urn:test"}'::jsonb),
