  (96716, '15ab844b-7bf3-4a55-9d9b-16596ec43c74'::uuid, 'R-(OLIGOPEPTIDE-133 SH-POLYPEPTIDE-11)', 'R-(OLIGOPEPTIDE-133 SH-POLYPEPTIDE-11)', NULL, NULL, NULL, 'r-(Oligopeptide-133 sh-Polypeptide-11) is a single chain fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the genes encoding for Oligopeptide-133 and sh-Polypeptide-11. The fusion peptide contains 166 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids,', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"15ab844b-7bf3-4a55-9d9b-16596ec43c74","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["R-(OLIGOPEPTIDE-133 SH-POLYPEPTIDE-11)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["r-(Oligopeptide-133 sh-Polypeptide-11) is a single chain fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the genes encoding for Oligopeptide-133 and sh-Polypeptide-11. The fusion peptide contains 166 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids,"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["AC6AC6D207179571A7731532E3522A91"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],