  (96718, 'b168cf57-b416-428d-ad02-f7cb57924c25'::uuid, 'S-HIV-1 OLIGOPEPTIDE-2 SP', 'S-HIV-1 OLIGOPEPTIDE-2 SP', NULL, NULL, NULL, 's-HIV-1 Oligopeptide-2 SP is a single chain protein containing 55 amino acids. It is synthetically produced based on the sequence for Gag-Pol Polyprotein which is found in the pathogenic virus, Human Immunodeficiency Virus-1 (HIV-1). It contains 246 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b168cf57-b416-428d-ad02-f7cb57924c25","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-HIV-1 OLIGOPEPTIDE-2 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-HIV-1 Oligopeptide-2 SP is a single chain protein containing 55 amino acids. It is synthetically produced based on the sequence for Gag-Pol Polyprotein which is found in the pathogenic virus, Human Immunodeficiency Virus-1 (HIV-1). It contains 246 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["B580AEA97A138FA327BE96B82200E27C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["S-HIV-1 OLIGOPEPTID