  (96907, '89c05467-cbf5-45a7-bf54-1269f6547a2d'::uuid, 'HEXYL/SUCCINYL DIMETHICONE CROSSPOLYMER', 'HEXYL/SUCCINYL DIMETHICONE CROSSPOLYMER', NULL, NULL, NULL, 'Hexyl/Succinyl Dimethicone Crosspolymer is a cross-linked dimethyl siloxane polymer that is formed by the reaction between Hydrogen Dimethicone and a combination of Allyl Succinic Anhydride and Hexene, followed by crosslinking with Hexanediol.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"89c05467-cbf5-45a7-bf54-1269f6547a2d","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["HEXYL/SUCCINYL DIMETHICONE CROSSPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Hexyl/Succinyl Dimethicone Crosspolymer is a cross-linked dimethyl siloxane polymer that is formed by the reaction between Hydrogen Dimethicone and a combination of Allyl Succinic Anhydride and Hexene, followed by crosslinking with Hexanediol."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["F118D260A63A2B93332CE4909C6D4C92"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["HEXYL/SUCCINYL DIMETHICONE CROSSPOLYMER"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96907"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":[