  (96908, 'a8216b46-9b5d-46fd-a7b2-76d53b190fa9'::uuid, 'POLYUREA CROSSPOLYMER-6', 'POLYUREA CROSSPOLYMER-6', NULL, NULL, '1,3-Propanediol, 2-ethyl-2-(hydroxymethyl)-, polymer with bis(isocyanatomethyl)benzene', 'Polyurea Crosspolymer-6 is a complex, highly cross-linked polymer formed by the reaction of Xylene Diisocyanate with Trimethylolpropane followed by partial hydrolysis and condensation to form urea bonds.', NULL, '610-745-9', NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a8216b46-9b5d-46fd-a7b2-76d53b190fa9","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYUREA CROSSPOLYMER-6"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["1,3-Propanediol, 2-ethyl-2-(hydroxymethyl)-, polymer with bis(isocyanatomethyl)benzene"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurea Crosspolymer-6 is a complex, highly cross-linked polymer formed by the reaction of Xylene Diisocyanate with Trimethylolpropane followed by partial hydrolysis and condensation to form urea bonds."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["853C32931F19E7BCF8313C661B06B3C5"],"cosmeticRestriction":[],"ecNo":["610-745-9"],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYUREA CROSSPOLYMER-6"],"esST_FileName":["file.txt"],"casNo":["51852-81-4"],"substanceId":["96908"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/p