  (96909, '4b49c99a-6ad0-41d0-99ef-e377cc7b8799'::uuid, 'POLYURETHANE-92', 'POLYURETHANE-92', NULL, NULL, NULL, 'Polyurethane-92 is a urethane polymer formed in a multi-step reaction. First, a polyester diol is made by reacting Hexanediol with Dimethyl Carbonate. The polyester diol is then reacted with Dimethylolbutyric Acid, 1,4-Butanediol and Isophorone Diisocyanate, to form a urethane/urea polymer, which is then reacted with Lysine. The resulting polymer is neutralized with Sodium Carbonate.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"4b49c99a-6ad0-41d0-99ef-e377cc7b8799","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-92"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-92 is a urethane polymer formed in a multi-step reaction. First, a polyester diol is made by reacting Hexanediol with Dimethyl Carbonate. The polyester diol is then reacted with Dimethylolbutyric Acid, 1,4-Butanediol and Isophorone Diisocyanate, to form a urethane/urea polymer, which is then reacted with Lysine. The resulting polymer is neutralized with Sodium Carbonate."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["E647F466AD745B741D0028E1AA432DA3"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-92"],"esST_FileN