  (96911, 'ec03cd68-d602-41f1-a7df-ece82ef48efe'::uuid, 'BIS-GLYCIDOXY DIMETHICONE/PEG-13 DIGLYCIDYL ETHER CROSSPOLYMER', 'BIS-GLYCIDOXY DIMETHICONE/PEG-13 DIGLYCIDYL ETHER CROSSPOLYMER', NULL, NULL, NULL, 'Bis-Glycidoxy Dimethicone/PEG-13 Diglycidyl Ether Crosspolymer is a complex silicone polymer formed by the reaction of a glycidoxypropyl-terminated dimethyl siloxane polymer with PEG-13 diglycidyl ether, and crosslinked by aminopropyltriisopropoxysilane.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"ec03cd68-d602-41f1-a7df-ece82ef48efe","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-GLYCIDOXY DIMETHICONE/PEG-13 DIGLYCIDYL ETHER CROSSPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-Glycidoxy Dimethicone/PEG-13 Diglycidyl Ether Crosspolymer is a complex silicone polymer formed by the reaction of a glycidoxypropyl-terminated dimethyl siloxane polymer with PEG-13 diglycidyl ether, and crosslinked by aminopropyltriisopropoxysilane."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["1D72C540C184CE9E980FBCD4C56234F0"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["BIS-GLYCIDOXY DIMETHICONE/PEG-13 DIGLYCIDYL ETHER CROSSPOLYMER"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96911"],"annexNo":[],"productTyp