  (96922, '45f92e6b-334f-43ad-8c4f-c421461883c4'::uuid, 'SACCHAROMYCES/HYDROLYZED OYSTER FERMENT EXTRACT', 'SACCHAROMYCES/HYDROLYZED OYSTER FERMENT EXTRACT', NULL, NULL, NULL, 'Saccharomyces/Hydrolyzed Oyster Ferment Extract is the extract of the product obtained by the fermentation of the hydrolysate of the meat of the oyster, Crassostrea gigas, by the microorganism Saccharomyces.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"45f92e6b-334f-43ad-8c4f-c421461883c4","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.3742867,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SACCHAROMYCES/HYDROLYZED OYSTER FERMENT EXTRACT"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Saccharomyces/Hydrolyzed Oyster Ferment Extract is the extract of the product obtained by the fermentation of the hydrolysate of the meat of the oyster, Crassostrea gigas, by the microorganism Saccharomyces."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["88154CF5AB197737D585457B665F89D7"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SACCHAROMYCES/HYDROLYZED OYSTER FERMENT EXTRACT"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96922"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HUMECTANT"],"esDA