  (96923, 'a698ad41-c4bc-48ba-989a-5a070f3cd3a0'::uuid, 'S-TERTIAPIN SP', 'S-TERTIAPIN SP', NULL, NULL, 'TPN', 's-Tertiapin SP is a single chain protein produced synthetically to be identical to Tertiapin, a presynaptic neurotoxin, which is found in the honeybee, Apis mellifera. The protein contains 21 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a698ad41-c4bc-48ba-989a-5a070f3cd3a0","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-TERTIAPIN SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["TPN"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Tertiapin SP is a single chain protein produced synthetically to be identical to Tertiapin, a presynaptic neurotoxin, which is found in the honeybee, Apis mellifera. The protein contains 21 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["B836DFB263B9648A1A4F879FC44B0118"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["S-TERTIAPIN SP"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96923"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_Conte