  (96924, 'e0d8322f-b310-4628-a423-6f01e1cc4331'::uuid, 'METHIONYL S-MELITTIN SP', 'METHIONYL S-MELITTIN SP', NULL, NULL, NULL, 'Methionyl s-Melittin SP is a single chain peptide synthetically produced to be identical to Melittin found in bee venom. The starting gene is synthesized by the fusion of the gene from s-Melittin with the initiation code for methionine. The peptide contains 70 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"e0d8322f-b310-4628-a423-6f01e1cc4331","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHIONYL S-MELITTIN SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methionyl s-Melittin SP is a single chain peptide synthetically produced to be identical to Melittin found in bee venom. The starting gene is synthesized by the fusion of the gene from s-Melittin with the initiation code for methionine. The peptide contains 70 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["AA21B43B4C4BB6C944223DC5B2BB9E74"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"