  (96928, '3a7d5622-bbcd-4834-a2d3-7e20ebd3571e'::uuid, 'SR-(CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 ALANYL SPIDER OLIGOPEPTIDE-1 HEXAPEPTIDE-40)', 'SR-(CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 ALANYL SPIDER OLIGOPEPTIDE-1 HEXAPEPTIDE-40)', NULL, NULL, NULL, 'sr-(Clostridium Botulinum Polypeptide-1 Alanyl Spider Oligopeptide-1 Hexapeptide-40) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sr-Clostridium Botulinum Polypeptide-1, sr-Spider Oligopeptide-1, and Hexapeptide-40 with the initiation code for alanine. The fusion peptide contains 497 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"3a7d5622-bbcd-4834-a2d3-7e20ebd3571e","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SR-(CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 ALANYL SPIDER OLIGOPEPTIDE-1 HEXAPEPTIDE-40)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-(Clostridium Botulinum Polypeptide-1 Alanyl Spider Oligopeptide-1 Hexapeptide-40) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sr-Clostridium Botulinum Polypeptide-1, sr-Spider Oligopeptide-1, and Hexapeptide-40 with the initiation code for alanine. The fusion peptide contains 497 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["4074A5A67E636124717E5E361DF91D7C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SR-(CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 ALANYL SPIDER OLIGOPEPTIDE-1 HEXAPEPTIDE-40)"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["96928"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN PROTECTING"],"esDA_IngestDate":["2023-05-23T07:55:03.165+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:55:03.137+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"3a7d5622-bbcd-4834-a2d3-7e20ebd3571e. Available at: urn:test"}'::jsonb),
  (96929, '608aa609-e0f5-4db5-8a04-08ddf832d5c8'::uuid, 'SR-(CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 JELLYFISH POLYPEPTIDE-1 HEXAPEPTIDE-40)', 'SR-(CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 JELLYFISH POLYPEPTIDE-1 HEXAPEPTIDE-40)', NULL, NULL, NULL, 'sr-(Clostridium Botulinum Polypeptide-1 Jellyfish Polypeptide-1 Hexapeptide-40) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from r-Clostridium Botulinum Polypeptide-1, sr-Jellyfish Polypeptide-1 and Hexapeptide-40. The fusion peptide contains 684 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"608aa609-e0f5-4db5-8a04-08ddf832d5c8","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SR-(CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 JELLYFISH POLYPEPTIDE-1 HEXAPEPTIDE-40)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-(Clostridium Botulinum Polypeptide-1 Jellyfish Polypeptide-1 Hexapeptide-40) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from r-Clostridium Botulinum Polypeptide-1, sr-Jellyfish Polypeptide-1 and Hexapeptide-40. The fusion peptide contains 684 amino acids which may contain disulfide bonds and/or glycosylation, an