  (96959, '3702b824-e708-419a-bf3e-6a2b2721405b'::uuid, 'SH-POLYPEPTIDE-121', 'SH-POLYPEPTIDE-121', NULL, NULL, NULL, 'sh-Polypeptide-121 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is synthesized to be identical to the human gene which codes for Collagen alpha-1(XXI) chain used such or adapted to the production host. It contains a maximum of 957 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"3702b824-e708-419a-bf3e-6a2b2721405b","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-121"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-121 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is synthesized to be identical to the human gene which codes for Collagen alpha-1(XXI) chain used such or adapted to the production host. It contains a maximum of 957 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["D217F4D421BC1746DA9BB2C2992ECFF4"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identif