  (96991, '9bf548c8-c795-41e8-b8fb-9079b380af47'::uuid, 'METHIONYL SH-POLYPEPTIDE-96', 'METHIONYL SH-POLYPEPTIDE-96', NULL, NULL, NULL, 'Methionyl sh-Polypeptide-96 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is synthesized by the addition of a methionyl initiation codon with the gene from sh-Polypeptide-96. It contains a maximum of 609 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"9bf548c8-c795-41e8-b8fb-9079b380af47","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHIONYL SH-POLYPEPTIDE-96"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methionyl sh-Polypeptide-96 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is synthesized by the addition of a methionyl initiation codon with the gene from sh-Polypeptide-96. It contains a maximum of 609 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["D5FB0CA6527A266A5D2B1CD3A7D64F9D"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJo