  (97060, '56251440-bc41-4ddc-bc53-b28df0df577c'::uuid, 'SH-HEXAPEPTIDE-6 SP AMIDE', 'SH-HEXAPEPTIDE-6 SP AMIDE', NULL, NULL, 'PAR-2', 'sh-Hexapeptide-6 SP Amide is a single chain human peptide, produced synthetically to be identical to a portion of the protein Proteinase-Activated Receptor 2, and contains 6 amino acids consisting of glycine, isoleucine, leucine, lysine, serine, and valine, in which the C-terminus is an amide.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"56251440-bc41-4ddc-bc53-b28df0df577c","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-HEXAPEPTIDE-6 SP AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["PAR-2"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Hexapeptide-6 SP Amide is a single chain human peptide, produced synthetically to be identical to a portion of the protein Proteinase-Activated Receptor 2, and contains 6 amino acids consisting of glycine, isoleucine, leucine, lysine, serine, and valine, in which the C-terminus is an amide."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["C9568200816830EE46B9A73B05BEB6A1"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SH-HEXAPEPTIDE-6 SP AMIDE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["97060"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/pla