  (97101, '8585a1b2-8e8a-40dd-9efa-d7436519ccb1'::uuid, 'RICE OLIGOPEPTIDE-91 SH-POLYPEPTIDE-1', 'RICE OLIGOPEPTIDE-91 SH-POLYPEPTIDE-1', NULL, NULL, NULL, 'Rice Oligopeptide-91 sh-Polypeptide-1 is a fusion peptide of Oligopeptide-91 and sh-Polypeptide-1 produced by rice plants after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The fusion peptide contains 167 amino acids and may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"8585a1b2-8e8a-40dd-9efa-d7436519ccb1","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.3742867,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["RICE OLIGOPEPTIDE-91 SH-POLYPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Rice Oligopeptide-91 sh-Polypeptide-1 is a fusion peptide of Oligopeptide-91 and sh-Polypeptide-1 produced by rice plants after using either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The fusion peptide contains 167 amino acids and may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["F122402D3E7803B00186F81E5F1C5422"],"cosmeticRestriction":[],"ecNo":