  (97109, '857f06b2-d8a6-4761-9052-ee9290c2627a'::uuid, 'SH-SPINORPHIN SP', 'SH-SPINORPHIN SP', NULL, NULL, 'L-leucyl-L-valyl-L-valyl-L-tyrosyl-L-prolyl-L-tryptophyl-L-threonine', 'sh-Spinorphin SP is a single chain protein produced synthetically to be identical to Spinorphin, which is a 7 amino acid peptide from the parent protein, Hemoglobin Subunit Beta. Hemoglobin Subunit Beta contains 147 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"857f06b2-d8a6-4761-9052-ee9290c2627a","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-SPINORPHIN SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["L-leucyl-L-valyl-L-valyl-L-tyrosyl-L-prolyl-L-tryptophyl-L-threonine"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Spinorphin SP is a single chain protein produced synthetically to be identical to Spinorphin, which is a 7 amino acid peptide from the parent protein, Hemoglobin Subunit Beta. Hemoglobin Subunit Beta contains 147 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["999F694584C5A93EF22B2D2956C43966"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officia