  (97121, '452b774b-8a52-4cd0-aa85-a10a5bba4cde'::uuid, 'SH-HEPTAPEPTIDE-6 SP', 'SH-HEPTAPEPTIDE-6 SP', NULL, NULL, NULL, 'sh-Heptapeptide-6 SP is the single chain human peptide produced synthetically to be identical to a portion of the protein Collagen Alpha-1 (XVI) Chain and contains 7 amino acids consisting of arginine, aspartic acid, glutamine, glycine and valine. Collagen Alpha-1 (XVI) chain contains a maximum of 1604 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"452b774b-8a52-4cd0-aa85-a10a5bba4cde","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-HEPTAPEPTIDE-6 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Heptapeptide-6 SP is the single chain human peptide produced synthetically to be identical to a portion of the protein Collagen Alpha-1 (XVI) Chain and contains 7 amino acids consisting of arginine, aspartic acid, glutamine, glycine and valine. Collagen Alpha-1 (XVI) chain contains a maximum of 1604 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["54A9ABB9A7024A4EE614439ECC16991E"],"cosmeticRestriction":[],"e