  (97122, 'ae77fd1c-fc3c-41c7-85ad-13111840de8a'::uuid, 'S-MUSSEL HEXAPEPTIDE-1 SP', 'S-MUSSEL HEXAPEPTIDE-1 SP', NULL, NULL, NULL, 's-Mussel Hexapeptide-1 SP is a single chain protein containing 6 amino acids. It is synthetically produced based on a sequence from Adhesive Plaque Matrix Protein which is found in the mussel, Mytilus edulis. Adhesive Plaque Matrix Protein contains 875 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"ae77fd1c-fc3c-41c7-85ad-13111840de8a","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.3742867,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-MUSSEL HEXAPEPTIDE-1 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Mussel Hexapeptide-1 SP is a single chain protein containing 6 amino acids. It is synthetically produced based on a sequence from Adhesive Plaque Matrix Protein which is found in the mussel, Mytilus edulis. Adhesive Plaque Matrix Protein contains 875 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["947F91E1202D374211F050419B1D0B93"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["S-MUSSEL HEXA