  (97256, 'f92461bd-4937-46a7-b415-6461450bf0ac'::uuid, 'SH-OLIGOPEPTIDE-95 SP', 'SH-OLIGOPEPTIDE-95 SP', NULL, NULL, 'HEST2,Telomerase-associated protein 2,Telomerase catalytic subunit,TP2', 'sh-Oligopeptide-95 SP is a 26 amino acid protein fragment produced synthetically to be identical to a portion of the human protein, Telomerase Reverse Transcriptase. The parent protein contains a maximum of 1132 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"f92461bd-4937-46a7-b415-6461450bf0ac","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-OLIGOPEPTIDE-95 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["HEST2,Telomerase-associated protein 2,Telomerase catalytic subunit,TP2"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Oligopeptide-95 SP is a 26 amino acid protein fragment produced synthetically to be identical to a portion of the human protein, Telomerase Reverse Transcriptase. The parent protein contains a maximum of 1132 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["54FD45E58D83E44E44EAF7A96B1ED39B"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":