  (97283, '50ea2663-3f6d-4f7f-82fd-2c62a642dd2e'::uuid, 'SR-(METHIONYL SHARK POLYPEPTIDE-1 DIPEPTIDE-19 HEXAPEPTIDE-40)', 'SR-(METHIONYL SHARK POLYPEPTIDE-1 DIPEPTIDE-19 HEXAPEPTIDE-40)', NULL, NULL, NULL, 'sr-(Methionyl Shark Polypeptide-1 Dipeptide-19 Hexapeptide-40) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sr-Shark Polypeptide-1, Dipeptide-19, and Hexapeptide-40 with the initiation code for methionine. The fusion peptide contains 183 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"50ea2663-3f6d-4f7f-82fd-2c62a642dd2e","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SR-(METHIONYL SHARK POLYPEPTIDE-1 DIPEPTIDE-19 HEXAPEPTIDE-40)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-(Methionyl Shark Polypeptide-1 Dipeptide-19 Hexapeptide-40) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sr-Shark Polypeptide-1, Dipeptide-19, and Hexapeptide-40 with the initiation code for methionine. The fusion peptide contains 183 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["44907D0A698FB0FA3FB9C3CAFC9BD9EF"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SR-(METHIONYL SHARK POLYPEPTIDE-1 DIPEPTIDE-19 HEXAPEPTIDE-40)"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["97283"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN PROTECTING"],"esDA_IngestDate":["2023-05-23T07:50:36.079+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:50:36.050+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"50ea2663-3f6d-4f7f-82fd-2c62a642dd2e. Available at: urn:test"}'::jsonb),
