  (97291, '0a490a2e-c604-4fec-aba8-93c0e90fbb25'::uuid, 'SR-(METHIONYL ELEPHANT POLYPEPTIDE-1 DIPEPTIDE-19 HEXAPEPTIDE-40)', 'SR-(METHIONYL ELEPHANT POLYPEPTIDE-1 DIPEPTIDE-19 HEXAPEPTIDE-40)', NULL, NULL, NULL, 'sr-(Methionyl Elephant Polypeptide-1 Dipeptide-19 Hexapeptide-40) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sr-Elephant Polypeptide-1, Dipeptide-19, and Hexapeptide-40 with the initiation code for methionine. The fusion peptide contains 199 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"0a490a2e-c604-4fec-aba8-93c0e90fbb25","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SR-(METHIONYL ELEPHANT POLYPEPTIDE-1 DIPEPTIDE-19 HEXAPEPTIDE-40)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-(Methionyl Elephant Polypeptide-1 Dipeptide-19 Hexapeptide-40) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sr-Elephant Polypeptide-1, Dipeptide-19, and Hexapeptide-40 with the initiation code for methionine. The fusion peptide contains 199 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["92BEDB9728A8AF0690CA14E676C43FEC"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SR-(METHIONYL ELEPHANT POLYPEPTIDE-1 DIPEPTIDE-19 HEXAPEPTIDE-40)"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["97291"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING","SKIN PROTECTING"],"esDA_IngestDate":["2023-05-23T07:50:37.875+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:50:37.851+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"0a490a2e-c604-4fec-aba8-93c0e90fbb25. Available at: urn:test"}'::jsonb),
