  (97332, '1d7c493c-3ae1-448a-b9e6-aeb23258a13d'::uuid, 'RH-POLYPEPTIDE-105', 'RH-POLYPEPTIDE-105', NULL, NULL, 'CXCL1,C-X-C Motif Chemokine 1,GRO-alpha(1-73),Melanoma Growth Stimulatory Activity,MGSA,NAP-3,Neutrophil-activating Protein 3', 'rh-Polypeptide-105 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is directly isolated from a human cell which codes for Growth-Regulated Alpha Protein or C-X-C Motif Chemokine Ligand 1 used as such or adapted to the production host. It contains a maximum of 107 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"1d7c493c-3ae1-448a-b9e6-aeb23258a13d","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["RH-POLYPEPTIDE-105"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["CXCL1,C-X-C Motif Chemokine 1,GRO-alpha(1-73),Melanoma Growth Stimulatory Activity,MGSA,NAP-3,Neutrophil-activating Protein 3"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["rh-Polypeptide-105 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene is directly isolated from a human cell which codes for Growth-Regulated Alpha Protein or C-X-C Motif Chemokine Ligand 1 used as such or adapted to the production host. It contains a maximum of 107 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["C1C678AE67ED0DDF9509948A45C5518E"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":["28761"],"officialJournalPublication":["Y"],"inciName":["RH-POLYPEPTIDE-105"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["97332"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HAIR CONDITIONING"],"esDA_IngestDate":["2023-05-23T07:58:28.242+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:58:28.218+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"1d7c493c-3ae1-448a-b9e6-aeb23258a13d. Available at: urn:test"}'::jsonb),
