  (97455, 'cc55c9f9-b14e-49c8-891f-3cacb6362b3f'::uuid, 'ACRYLOYLOXYPROPYL SILSESQUIOXANE/TRIMETHYLSILOXYSILICATE/BUTYL ACRYLATE CROSSPOLYMER', 'ACRYLOYLOXYPROPYL SILSESQUIOXANE/TRIMETHYLSILOXYSILICATE/BUTYL ACRYLATE CROSSPOLYMER', NULL, NULL, NULL, 'Acryloyloxypropyl Silsesquioxane/Trimethylsiloxysilicate/Butyl Acrylate Crosspolymer is made by a multi-step process. First, a silicate resin is prepared by the hydrolysis and condensation of tetramethoxysilane, trimethylmethoxysilane, and Acryloyloxy Propyltrimethoxysilane. This silicate resin is then copolymerized with Butyl Acrylate.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"cc55c9f9-b14e-49c8-891f-3cacb6362b3f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["ACRYLOYLOXYPROPYL SILSESQUIOXANE/TRIMETHYLSILOXYSILICATE/BUTYL ACRYLATE CROSSPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Acryloyloxypropyl Silsesquioxane/Trimethylsiloxysilicate/Butyl Acrylate Crosspolymer is made by a multi-step process. First, a silicate resin is prepared by the hydrolysis and condensation of tetramethoxysilane, trimethylmethoxysilane, and Acryloyloxy Propyltrimethoxysilane. This silicate resin is then copolymerized with Butyl Acrylate."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["7020AB5BA7D619AE9702959435CDAB71"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentrat