  (97463, '5e50318d-b7bb-4a25-8c3a-c98fed2a308f'::uuid, 'POLYURETHANE-96', 'POLYURETHANE-96', NULL, NULL, NULL, 'olyurethane-96 is the urethane polymer formed by reacting a polymeric diol with Isophorone Diisocyanate. The urethane polymer is capped with 2-Hydroxypropyl Acrylate. The polymeric diol is composed of Hexanediol and 1,5-Pentanediol condensed with Ethylene Carbonate.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"5e50318d-b7bb-4a25-8c3a-c98fed2a308f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-96"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["olyurethane-96 is the urethane polymer formed by reacting a polymeric diol with Isophorone Diisocyanate. The urethane polymer is capped with 2-Hydroxypropyl Acrylate. The polymeric diol is composed of Hexanediol and 1,5-Pentanediol condensed with Ethylene Carbonate."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["B34B4FCF428E7E122512392E2C0CAF55"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-96"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["97463"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["BINDING","NAIL CONDITIONING