  (97517, '2ed1d408-5a30-4dac-8522-bf7f9cd04d32'::uuid, 'SH-PENTAPEPTIDE-12 SP', 'SH-PENTAPEPTIDE-12 SP', NULL, NULL, 'Connectin', 'sh-Pentapeptide-12 SP is a single chain human peptide produced synthetically to be identical to a portion of the protein, Titin, and contains 5 amino acids consisting of isoleucine, leucine, lysine and phenylalanine. The parent protein contains a maximum of 34,350 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"2ed1d408-5a30-4dac-8522-bf7f9cd04d32","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-PENTAPEPTIDE-12 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Connectin"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Pentapeptide-12 SP is a single chain human peptide produced synthetically to be identical to a portion of the protein, Titin, and contains 5 amino acids consisting of isoleucine, leucine, lysine and phenylalanine. The parent protein contains a maximum of 34,350 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["9393710D89B023947E0D6EA0A9556664"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJour