  (97637, 'f8f487d5-5f00-48eb-afd7-6a856c6ffb74'::uuid, 'METHIONYL RH-POLYPEPTIDE-83', 'METHIONYL RH-POLYPEPTIDE-83', NULL, NULL, NULL, 'Methionyl rh-Polypeptide-83 is a single chain fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from rh-Polypeptide-83 with the initiation code for methionine. The fusion peptide contains 50 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"f8f487d5-5f00-48eb-afd7-6a856c6ffb74","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHIONYL RH-POLYPEPTIDE-83"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methionyl rh-Polypeptide-83 is a single chain fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from rh-Polypeptide-83 with the initiation code for methionine. The fusion peptide contains 50 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["FEF61FB52D670CA752104280F2F7D574"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":["28761"],"inciName":["METHIONYL RH-POLYPEPTIDE-83"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["97637