  (97654, 'd2cd36b9-2780-4baa-a623-3bbfc21f47af'::uuid, 'S-OCTOPUS PENTAPEPTIDE-1 SP', 'S-OCTOPUS PENTAPEPTIDE-1 SP', NULL, NULL, NULL, 's-Octopus Pentapeptide-1 SP is a single chain peptide consisting of arginine, isoleucine, leucine and proline. It is synthetically produced based on a sequence from S1 Type peptidase found in the octopus Hapalochlaena maculosa. The parent protein contains a maximum of 182 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"d2cd36b9-2780-4baa-a623-3bbfc21f47af","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-OCTOPUS PENTAPEPTIDE-1 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Octopus Pentapeptide-1 SP is a single chain peptide consisting of arginine, isoleucine, leucine and proline. It is synthetically produced based on a sequence from S1 Type peptidase found in the octopus Hapalochlaena maculosa. The parent protein contains a maximum of 182 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["CC3DC4B18EF40116573A8C7CC04EEC25"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":