  (98033, '945287e5-cb36-4fc0-9fe1-f188213ad3f7'::uuid, 'POLYACRYLATE-53', 'POLYACRYLATE-53', NULL, NULL, NULL, 'Polyacrylate-53 is a complex polymer that is formed in a multi-step reaction. First, a polymer is created by the reaction of Styrene, Ethylhexyl Acrylate, and Hydroxypropyl Methacrylate PEG-13/PPG-2 Ether. Next, the polymer is reacted with Succinic Anhydride followed by sulfonation and neutralization to produce the sodium salt.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"945287e5-cb36-4fc0-9fe1-f188213ad3f7","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9887555,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYACRYLATE-53"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyacrylate-53 is a complex polymer that is formed in a multi-step reaction. First, a polymer is created by the reaction of Styrene, Ethylhexyl Acrylate, and Hydroxypropyl Methacrylate PEG-13/PPG-2 Ether. Next, the polymer is reacted with Succinic Anhydride followed by sulfonation and neutralization to produce the sodium salt."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["0CC8E64EB57B89F81E20A0D2D60B2E97"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYACRYLATE-53"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["98033"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_Con