  (98050, '73589377-63d8-4db5-8720-3fce90c0b5d1'::uuid, 'METHIONYL RH-POLYPEPTIDE-125', 'METHIONYL RH-POLYPEPTIDE-125', NULL, NULL, NULL, 'Methionyl rh-Polypeptide-125 is a single chain fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from rh-Polypeptide-125 with the initiation code for methionine. The fusion peptide contains 112 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"73589377-63d8-4db5-8720-3fce90c0b5d1","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["METHIONYL RH-POLYPEPTIDE-125"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methionyl rh-Polypeptide-125 is a single chain fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from rh-Polypeptide-125 with the initiation code for methionine. The fusion peptide contains 112 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["D8011F913BD4ECE2364434C790BCEEE3"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":["28761"],"inciName":["METHIONYL RH-POLYPEPTIDE-125"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceI