  (98053, '4838baa8-6289-42dd-9d46-afbee60edf65'::uuid, 'ACETYL NORLEUCYL DIPEPTIDE-54 D-PHENYLALANYL DIPEPTIDE-25 AMIDE', 'ACETYL NORLEUCYL DIPEPTIDE-54 D-PHENYLALANYL DIPEPTIDE-25 AMIDE', NULL, NULL, NULL, 'Acetyl Norleucyl Dipeptide-54 D-Phenylalanyl Dipeptide-25 Amide is the product obtained by the acetylation of the peptide consisting of norleucine, Dipeptide-54, D-phenylalanine and Dipeptide-25 in which the C-terminus is an amide.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"4838baa8-6289-42dd-9d46-afbee60edf65","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["ACETYL NORLEUCYL DIPEPTIDE-54 D-PHENYLALANYL DIPEPTIDE-25 AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Acetyl Norleucyl Dipeptide-54 D-Phenylalanyl Dipeptide-25 Amide is the product obtained by the acetylation of the peptide consisting of norleucine, Dipeptide-54, D-phenylalanine and Dipeptide-25 in which the C-terminus is an amide."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["BE09FDAD7ACDA17AFF8B64BC2F80DB91"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["ACETYL NORLEUCYL DIPEPTIDE-54 D-PHENYLALANYL DIPEPTIDE-25 AMIDE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["98053"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_Content