  (98054, 'd92dc7f9-7320-41ae-9a0e-dcf9a43d0bd4'::uuid, 'SR-(METHIONYL OLIGOPEPTIDE-91 GLUTAMINYL CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 HEXAPEPTIDE-40)', 'SR-(METHIONYL OLIGOPEPTIDE-91 GLUTAMINYL CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 HEXAPEPTIDE-40)', NULL, NULL, NULL, 'sr-(Methionyl Oligopeptide-91 Glutaminyl Clostridium Botulinum Polypeptide-1 Hexapeptide-40) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from Oligopeptide-91, sr-Clostridium Botulinum Polypeptide-1 and Hexapeptide-40 with the initiation code for methionine and glutamine. The fusion peptide contains 475 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"d92dc7f9-7320-41ae-9a0e-dcf9a43d0bd4","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SR-(METHIONYL OLIGOPEPTIDE-91 GLUTAMINYL CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 HEXAPEPTIDE-40)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-(Methionyl Oligopeptide-91 Glutaminyl Clostridium Botulinum Polypeptide-1 Hexapeptide-40) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from Oligopeptide-91, sr-Clostridium Botulinum Polypeptide-1 and Hexapeptide-40 with the initiation code for methionine and glutamine. The fusion peptide contains 475 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["04B08D4E350EE726443BE8950CE21AC9"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SR-(METHIONYL OLIGOPEPTIDE-91 GLUTAMINYL CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 HEXAPEPTIDE-40)"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["98054"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - EMOLLIENT","SKIN CONDITIONING","SKIN PROTECTING"],"esDA_IngestDate":["2023-05-23T07:51:55.167+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:51:55.148+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"d92dc7f9-7320-41ae-9a0e-dcf9a43d0bd4. Available at: urn:test"}'::jsonb),
