  (98068, '9cc8f204-d5bc-4470-a5fc-73a63b38c503'::uuid, 'CHLORELLA VULGARIS SH-OLIGOPEPTIDE-1', 'CHLORELLA VULGARIS SH-OLIGOPEPTIDE-1', NULL, NULL, NULL, 'Chlorella Vulgaris sh-Oligopeptide-1 is a single chain recombinant human peptide, produced by Chollera vulgaris, after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Epidermal Growth Factor. It contains a maximum of 53 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"9cc8f204-d5bc-4470-a5fc-73a63b38c503","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["CHLORELLA VULGARIS SH-OLIGOPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Chlorella Vulgaris sh-Oligopeptide-1 is a single chain recombinant human peptide, produced by Chollera vulgaris, after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Epidermal Growth Factor. It contains a maximum of 53 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["43F19BCA57886F75AF78395702F31CBC"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["CHLORELLA VULGARIS SH-OLIGOPEPTIDE-1"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["98068"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIMICROBIAL","ANTIOXIDANT","HAIR CONDITIONING","HUMECTANT","SKIN CONDITIONING","SKIN PROTECTING"],"esDA_IngestDate":["2023-05-23T07:51:58.507+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:51:58.439+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"9cc8f204-d5bc-4470-a5fc-73a63b38c503. Available at: urn:test"}'::jsonb),
  (98069, 'ceea5a3f-b906-4c09-9d8b-374ec7333279'::uuid, 'CHLORELLA VULGARIS SH-POLYPEPTIDE-14', 'CHLORELLA VULGARIS SH-POLYPEPTIDE-14', NULL, NULL, NULL, 'Chlorella Vulgaris sh-Polypeptide-14 is a single chain recombinant human peptide, produced Chollera vulgaris after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Nerve Growth Factor Beta. It contains a maximum of 53 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"ceea5a3f-b906-4c09-9d8b-374ec7333279","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["CHLORELLA VULGARIS SH-POLYPEPTIDE-14"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Chlorella Vulgaris sh-Polypeptide-14 is a single chain recombinant human peptide, produced Chollera vulgaris after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Nerve Growth Factor Beta. It contains a maximum of 53 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the pr