  (98071, 'bec93cca-7ef0-440f-9b9e-eb9f3d51c7d5'::uuid, 'HUMAN AMNIOTIC FLUID MESENCHYMAL STEM CELL/TROPHOBLAST CELL EXOSOMES', 'Human Amniotic Fluid Mesenchymal Stem Cell/Trophoblast Cell Exosomes', NULL, 'Human Amniotic Fluid Mesenchymal Stem Cell/Trophoblast Cell Exosomes', NULL, 'Human Amniotic Fluid Mesenchymal Stem Cell/Trophoblast Cell Exosomes are vesicles that are secreted into the conditioned media by human amniotic fluid mesenchymal stem cells and human trophoblast cells.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"bec93cca-7ef0-440f-9b9e-eb9f3d51c7d5","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Human Amniotic Fluid Mesenchymal Stem Cell/Trophoblast Cell Exosomes"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Human Amniotic Fluid Mesenchymal Stem Cell/Trophoblast Cell Exosomes are vesicles that are secreted into the conditioned media by human amniotic fluid mesenchymal stem cells and human trophoblast cells."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["D637AEF4729866D913500C713F7B2058"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["HUMAN AMNIOTIC FLUID MESENCHYMAL STEM CELL/TROPHOBLAST CELL EXOSOMES"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["98071"],"annexNo":[],"productType