  (98118, '4b5d4055-d54d-494e-92e2-1720346aefde'::uuid, 'RH-POLYPEPTIDE-125', 'RH-POLYPEPTIDE-125', NULL, NULL, NULL, 'rh-Polypeptide-125 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene which is isolated from a human cell and codes for Platelet-Derived Growth Factor C is used as such or adapted to the production host. It contains a maximum of 345 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"4b5d4055-d54d-494e-92e2-1720346aefde","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["RH-POLYPEPTIDE-125"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["rh-Polypeptide-125 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene which is isolated from a human cell and codes for Platelet-Derived Growth Factor C is used as such or adapted to the production host. It contains a maximum of 345 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["B902531B347C455E2E1225EED0B0143F"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"iden