  (98419, 'e8ad6ad3-844a-4d66-955f-d0ee8a73ce2f'::uuid, 'R-(SH-POLYPEPTIDE-69 TRIPEPTIDE-78 SH-POLYPEPTIDE-69 ASPARTYL HEXAPEPTIDE-40 HEXAPEPTIDE-78)', 'R-(SH-POLYPEPTIDE-69 TRIPEPTIDE-78 SH-POLYPEPTIDE-69 ASPARTYL HEXAPEPTIDE-40 HEXAPEPTIDE-78)', NULL, NULL, NULL, 'r-(sh-Polypeptide-69 Tripeptide-78 sh-Polypeptide-69 Aspartyl Hexapeptide-40 Hexapeptide-78) is a single chain recombinant peptide, produced by fermentation in Pichia pastorisi. The starting gene is synthesized by the fusion of the genes encoding for sh-Polypeptide-69, Tripeptide-78, sh-Polypeptide-69, Hexapeptide-40 and Hexapeptide-78 with the initiation code for aspartic acid. The fusion peptide contains 474 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"e8ad6ad3-844a-4d66-955f-d0ee8a73ce2f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":2.3191361,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["R-(SH-POLYPEPTIDE-69 TRIPEPTIDE-78 SH-POLYPEPTIDE-69 ASPARTYL HEXAPEPTIDE-40 HEXAPEPTIDE-78)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["r-(sh-Polypeptide-69 Tripeptide-78 sh-Polypeptide-69 Aspartyl Hexapeptide-40 Hexapeptide-78) is a single chain recombinant peptide, produced by fermentation in Pichia pastorisi. The starting gene is synthesized by the fusion of the genes encoding for sh-Polypeptide-69, Tripeptide-78, sh-Polypeptide-69, Hexapeptide-40 and Hexapeptide-78 with the initiation code for aspartic acid. The fusion peptide contains 474 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["53E79929C7D2D66EE3D978D4D425C56B"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["R-(SH-POLYPEPTIDE-69 TRIPEPTIDE-78 SH-POLYPEPTIDE-69 ASPARTYL HEXAPEPTIDE-40 HEXAPEPTIDE-78)"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["98419"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING","SKIN PROTECTING"],"esDA_IngestDate":["2023-05-23T07:51:24.730+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:51:24.705+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"e8ad6ad3-844a-4d66-955f-d0ee8a73ce2f. Available at: urn:test"}'::jsonb),
