  (98422, '23b92a72-d545-4d3b-9252-b9ab506d5466'::uuid, 'SH-POLYPEPTIDE-127', 'SH-POLYPEPTIDE-127', NULL, NULL, NULL, 'sh-Polypeptide-127 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene which is a synthesized copy of the human gene that codes for Cellular Tumor Antigen p53 is used as such or adapted to the production host. It contains a maximum of 393 amino acids which may contain disulfide bonds and/or glycosylation.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"23b92a72-d545-4d3b-9252-b9ab506d5466","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-127"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-127 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene which is a synthesized copy of the human gene that codes for Cellular Tumor Antigen p53 is used as such or adapted to the production host. It contains a maximum of 393 amino acids which may contain disulfide bonds and/or glycosylation."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["5D0CF1517DA074C88514B27DD6C843DC"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SH-POLYPEPTIDE-127"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["98422"]