  (98637, '6a6b3a23-ef22-46c1-b08a-8250c2eff962'::uuid, 'SH-OCTAPEPTIDE-6 SP', 'SH-OCTAPEPTIDE-6 SP', NULL, NULL, 'sh-Octapeptide-6 SP', 'sh-Octapeptide-6 SP is a single chain human peptide, produced synthetically to be identical to a portion of the protein, 40S ribosomal protein S3, and contains 8 amino acids consisting of glycine, isoleucine, leucine, lysine, methionine and valine. The parent protein contains a maximum of 243 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"6a6b3a23-ef22-46c1-b08a-8250c2eff962","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-OCTAPEPTIDE-6 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["sh-Octapeptide-6 SP"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Octapeptide-6 SP is a single chain human peptide, produced synthetically to be identical to a portion of the protein, 40S ribosomal protein S3, and contains 8 amino acids consisting of glycine, isoleucine, leucine, lysine, methionine and valine. The parent protein contains a maximum of 243 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["B89A444C72A3E8FC17F8581F83D23087"],"cosmeticRestriction":[],"ecN