  (98675, '65dcf470-eb7c-4e92-bfb4-57fb44a8b8aa'::uuid, 'ASPERGILLUS/CITRUS RETICULATA × SINENSIS FRUIT/RICE/STRAWBERRY FRUIT FERMENT FILTRATE', 'ASPERGILLUS/CITRUS RETICULATA × SINENSIS FRUIT/RICE/STRAWBERRY FRUIT FERMENT FILTRATE', NULL, NULL, 'Aspergillus/Citrus Reticulata × Sinensis Fruit/Rice/Strawberry Fruit Ferment Filtrate', 'Aspergillus/Citrus Reticulata × Sinensis Fruit/Rice/Strawberry Fruit Ferment Filtrate is a filtrate of the product obtained by the fermentation of the fruits of Citrus reticulata x sinensis and Fragaria ananassa and the grains of Oryza sativa by the microorganism, Aspergillus. The accepted scientific name for Citrus reticulata is Citrus reticulata x sinensis ''Reiko''.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"65dcf470-eb7c-4e92-bfb4-57fb44a8b8aa","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["ASPERGILLUS/CITRUS RETICULATA × SINENSIS FRUIT/RICE/STRAWBERRY FRUIT FERMENT FILTRATE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["Aspergillus/Citrus Reticulata × Sinensis Fruit/Rice/Strawberry Fruit Ferment Filtrate"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Aspergillus/Citrus Reticulata × Sinensis Fruit/Rice/Strawberry Fruit Ferment Filtrate is a filtrate of the product obtained by the fermentation of the fruits of Citrus reticulata x sinensis and Fragaria ananassa and the grains of Oryza sativa by the microorganism, Aspergillus. The accepted scientific name for Citrus reticulata is Citrus reticulata x sinensis ''Reiko''."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["485605903FE4110CDE21DA0CA521ABD4"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["ASPERGILLUS/CITRUS RETICULATA × SINENSIS FRUIT/RICE/STRAWBERRY FRUIT FERMENT FILTRATE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["98675"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - MISCELLANEOUS"],"esDA_IngestDate":["2023-05-23T07:58:57.986+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:58:57.956+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"65dcf470-eb7c-4e92-bfb4-57fb44a8b8aa. Available at: urn:test"}'::jsonb),
  (98676, 'b642d88d-7d84-4256-ae4a-a76dd174c158'::uuid, 'SH-OLIGOPEPTIDE-85 SP', 'SH-OLIGOPEPTIDE-85 SP', NULL, NULL, 'sh-Oligopeptide-85 SP', 'sh-Oligopeptide-85 SP is a 11 amino acid protein fragment produced synthetically to be identical to a portion of the human protein, Diskerin. The parent protein contains a maximum of 514 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b642d88d-7d84-4256-ae4a-a76dd174c158","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-OLIGOPEPTIDE-85 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["sh-Oligopeptide-85 SP"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Oligopeptide-85 SP is a 11 amino acid protein fragment produced synthetically to be identical to a portion of the human protein, Diskerin. The parent protein contains a maximum of 514 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["6F7B1CE8C201EDF645A848B03AA9E85C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SH-OLIGOPEPTIDE-85 SP"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["98676"],"annexNo"