  (98744, '8e41749e-9545-4351-b1d4-164b9d760625'::uuid, 'HUMAN CORONAVIRUS OLIGOPEPTIDE-1 SP', 'HUMAN CORONAVIRUS OLIGOPEPTIDE-1 SP', NULL, NULL, 'Human Coronavirus Oligopeptide-1 SP', 'Human Coronavirus Oligopeptide-1 SP is a single chain protein containing 36 amino acids. It is synthetically produced based on the sequence for Spike Glycoprotein which is found in the pathogenic virus, Human Coronavirus 229E. It contains 133 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"8e41749e-9545-4351-b1d4-164b9d760625","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["HUMAN CORONAVIRUS OLIGOPEPTIDE-1 SP"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":["Human Coronavirus Oligopeptide-1 SP"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Human Coronavirus Oligopeptide-1 SP is a single chain protein containing 36 amino acids. It is synthetically produced based on the sequence for Spike Glycoprotein which is found in the pathogenic virus, Human Coronavirus 229E. It contains 133 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["4102244684F0BB44A5061320715EC030"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["HUMAN CORONAVIRUS OLIGOPEPTIDE-1 SP"],"officialJournalPublication":["Y"],"es