  (98749, 'b96a111a-dceb-4e35-aa3d-00da6a4fd12c'::uuid, 'S-COCONUT ANTIMICROBIAL PEPTIDE 1', 'S-COCONUT ANTIMICROBIAL PEPTIDE 1', NULL, NULL, 's-Coconut Antimicrobial Peptide 1', 's-Coconut Antimicrobial Peptide 1 is a single chain protein produced synthetically to be identical to the protein, Antimicrobial Peptide 1 found in the coconut, Cocos nuciferus. Antimicrobial Peptide 1 contains a maximum of 9 amino acids which may contain glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"b96a111a-dceb-4e35-aa3d-00da6a4fd12c","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-COCONUT ANTIMICROBIAL PEPTIDE 1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":["s-Coconut Antimicrobial Peptide 1"],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Coconut Antimicrobial Peptide 1 is a single chain protein produced synthetically to be identical to the protein, Antimicrobial Peptide 1 found in the coconut, Cocos nuciferus. Antimicrobial Peptide 1 contains a maximum of 9 amino acids which may contain glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["C0CD7E5B250DBDCEE39A20267DF30BC2"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["S-COCO