  (98773, '765a3ea2-aa32-4b7e-a994-9beadf211fbd'::uuid, 'SR-(SH-POLYPEPTIDE-129 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-117 SH-POLYPEPTIDE-94 SH-POLYPEPTIDE-95 PENTAPEPTIDE-63 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-6 NONAPEPTIDE-43 SH-POLYPEPTIDE-6) DIMER', 'SR-(SH-POLYPEPTIDE-129 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-117 SH-POLYPEPTIDE-94 SH-POLYPEPTIDE-95 PENTAPEPTIDE-63 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-6 NONAPEPTIDE-43 SH-POLYPEPTIDE-6) DIMER', NULL, NULL, 'sr-(sh-Polypeptide-129 Oligopeptide-163 sh-Polypeptide-117 sh-Polypeptide-94 sh-Polypeptide-95 Pentapeptide-63 Oligopeptide-163 sh-Polypeptide-6 Nonapeptide-43 sh-Polypeptide-6) Dimer', 'This peptide is a dimer linked by a disulfide bridge between the cysteines, consisting of a single chain synthetic fusion peptide produced by fermentation in Chinese hamster ovary (CHO) cells. The starting gene is synthesized by the fusion of the genes from sh-Polypeptide-129, Oligopeptide-163, sh-Polypeptide-117, sh-Polypeptide-94, sh-Polypeptide-95, Pentapeptide-63, Oligopeptide-163, sh-Polypeptide-6 and Nonapeptide-43. This fusion protein contains 613 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"765a3ea2-aa32-4b7e-a994-9beadf211fbd","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SR-(SH-POLYPEPTIDE-129 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-117 SH-POLYPEPTIDE-94 SH-POLYPEPTIDE-95 PENTAPEPTIDE-63 OLIGOPEPTIDE-163 SH-POLYPEPTIDE-6 NONAPEPTIDE-43 SH-POLYPEPTIDE-6) DIMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsO