  (98909, '5b1d86fc-3c4b-4663-bab6-1d76107f9c2d'::uuid, 'TRIMETHYLSILYL ALANINE PG-PROPYL METHYLSILANEDIOL CROSSPOLYMER', 'TRIMETHYLSILYL ALANINE PG-PROPYL METHYLSILANEDIOL CROSSPOLYMER', NULL, NULL, NULL, 'Trimethylsilyl Alanine PG-Propyl Methylsilanediol Crosspolymer is the reaction product of Alanine that has been condensed with glycidoxypropylmethyldiethoxysilane followed by hydrolysis to produce the silane diol. Then the silane diol is crosslinked by condensation with hydrolyzed methyltriethoxysilane, hydrolyzed dimethyldiethoxysilane, and hydrolyzed C6-10 alkyl triethoxysilane, and end-capped with hydrolyzed trimethylchlorosilane.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"5b1d86fc-3c4b-4663-bab6-1d76107f9c2d","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["TRIMETHYLSILYL ALANINE PG-PROPYL METHYLSILANEDIOL CROSSPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Trimethylsilyl Alanine PG-Propyl Methylsilanediol Crosspolymer is the reaction product of Alanine that has been condensed with glycidoxypropylmethyldiethoxysilane followed by hydrolysis to produce the silane diol. Then the silane diol is crosslinked by condensation with hydrolyzed methyltriethoxysilane, hydrolyzed dimethyldiethoxysilane, and hydrolyzed C6-10 alkyl triethoxysilane, and end-capped with hydrolyzed trimethylchlorosilane."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41