  (98976, '5c2e9ddc-92b9-42b6-bdaa-61ee0bd52fea'::uuid, 'NICOTIANA BENTHAMIANA HEXAPEPTIDE-40 SH-POLYPEPTIDE-133 TETRAPEPTIDE-78', 'NICOTIANA BENTHAMIANA HEXAPEPTIDE-40 SH-POLYPEPTIDE-133 TETRAPEPTIDE-78', NULL, NULL, NULL, 'Nicotiana Benthamiana Hexapeptide-40 sh-Polypeptide-133 Tetrapeptide-78 is a fusion peptide of Hexapeptide-40 and sh-Polypeptide-133 and Tetrapeptide-78 produced by Nicotiana benthamiana after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The fusion peptide contains 1132 amino acids and may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"5c2e9ddc-92b9-42b6-bdaa-61ee0bd52fea","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["NICOTIANA BENTHAMIANA HEXAPEPTIDE-40 SH-POLYPEPTIDE-133 TETRAPEPTIDE-78"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Nicotiana Benthamiana Hexapeptide-40 sh-Polypeptide-133 Tetrapeptide-78 is a fusion peptide of Hexapeptide-40 and sh-Polypeptide-133 and Tetrapeptide-78 produced by Nicotiana benthamiana after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The fusion peptide contains 1132 amino acids and may contain disulfide bonds and/o