  (98988, '1ed0e815-a9d0-42e7-9182-13efbf7b9237'::uuid, 'SH-POLYPEPTIDE-132', 'SH-POLYPEPTIDE-132', NULL, NULL, NULL, 'sh-Polypeptide-132 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene which is a synthesized copy of the human gene that codes for Laminin Subunit Gamma-2 is used such or adapted to the production host. It contains a maximum of 1193 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"1ed0e815-a9d0-42e7-9182-13efbf7b9237","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-POLYPEPTIDE-132"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Polypeptide-132 is a single chain recombinant human peptide, produced by fermentation in E. coli. The starting gene which is a synthesized copy of the human gene that codes for Laminin Subunit Gamma-2 is used such or adapted to the production host. It contains a maximum of 1193 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["B130E12040F89E738BF40899DB1B98B4"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngred