  (99058, '44e86027-877f-4e47-9bde-0a6622b583a4'::uuid, 'SR-(CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 OLIGOPEPTIDE-192 CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 OLIGOPEPTIDE-192 OLIGOPEPTIDE-193)', 'SR-(CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 OLIGOPEPTIDE-192 CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 OLIGOPEPTIDE-192 OLIGOPEPTIDE-193)', NULL, NULL, NULL, 'sr-(Clostridium Botulinum Polypeptide-1 Oligopeptide-192 Clostridium Botulinum Polypeptide-1 Oligopeptide-192 Oligopeptide-193) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sr-Clostridium Botulinum Polypeptide-1, Oligopeptide-192 and Oligopeptide-193. The fusion peptide contains 507 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"44e86027-877f-4e47-9bde-0a6622b583a4","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SR-(CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 OLIGOPEPTIDE-192 CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 OLIGOPEPTIDE-192 OLIGOPEPTIDE-193)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-(Clostridium Botulinum Polypeptide-1 Oligopeptide-192 Clostridium Botulinum Polypeptide-1 Oligopeptide-192 Oligopeptide-193) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from sr-Clostridium Botulinum Polypeptide-1, Oligopeptide-192 and Oligopeptide-193. The fusion peptide contains 507 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["75C5C0B509554CC79D740D0C7EAD27C6"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SR-(CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 OLIGOPEPTIDE-192 CLOSTRIDIUM BOTULINUM POLYPEPTIDE-1 OLIGOPEPTIDE-192 OLIGOPEPTIDE-193)"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["99058"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN PROTECTING","SKIN CONDITIONING - MISCELLANEOUS"],"esDA_IngestDate":["2023-05-23T07:57:43.887+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T07:57:43.857+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"44e86027-877f-4e47-9bde-0a6622b583a4. Available at: urn:test"}'::jsonb),
  (99059, '185aff6b-e6a1-4b92-b5a0-4c8f4e3c9b03'::uuid, 'S-RICE POLYPEPTIDE-1', 'S-RICE POLYPEPTIDE-1', NULL, NULL, NULL, 's-Rice Polypeptide-1 is a single chain peptide produced synthetically to be identical to the protein, Glucose-1-Phosphate Adenylyltransferase Small Subunit 2, Chloroplastic/Amyloplastic/Cytosolic, derived from Oryza sativa. The protein contains a maximum of 504 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"185aff6b-e6a1-4b92-b5a0-4c8f4e3c9b03","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-RICE POLYPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Rice Polypeptide-1 is a single chain peptide produced synthetically to be identical to the protein, Glucose-1-Phosphate Adenylyltransferase Small Subunit 2, Chloroplastic/Amyloplastic/Cytosolic, derived from Oryza sativa. The protein contains a maximum of 504 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["B3CA63975FF6E31F7EC5F7B3B931FB86"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciN