  (99060, 'bbecbaac-8255-4f0c-b913-24de1703f637'::uuid, 'S-RICE POLYPEPTIDE-2', 'S-RICE POLYPEPTIDE-2', NULL, NULL, NULL, 's-Rice Polypeptide-2 is a single chain peptide produced synthetically to be identical to the protein, 40S Ribosomal Protein S15, Putative, Expressed, derived from Oryza sativa. The protein contains a maximum of 154 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"bbecbaac-8255-4f0c-b913-24de1703f637","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-RICE POLYPEPTIDE-2"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Rice Polypeptide-2 is a single chain peptide produced synthetically to be identical to the protein, 40S Ribosomal Protein S15, Putative, Expressed, derived from Oryza sativa. The protein contains a maximum of 154 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["9695850AEF318E3472EE8BC27FB98C10"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["S-RICE POLYPEPTIDE-2"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["99060"],