  (99086, '33e0d2af-b138-4570-9c4e-ecf2c48820be'::uuid, 'POLYESTER-40', 'POLYESTER-40', NULL, NULL, NULL, 'Polyester-40 is a copolymer that is formed by the condensation of hydrogenated dimer acids and hydrogenated dimer alcohols. The copolymer is capped with Stearic Acid (q.v.). The hydrogenated dimer acids are made from Rapeseed Acid by reacting the unsaturated fatty acids followed by hydrogenation. The dimer alcohols are produced by reducing the acid groups on the hydrogenated dimer acids to convert them to hydroxyl groups.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"33e0d2af-b138-4570-9c4e-ecf2c48820be","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYESTER-40"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyester-40 is a copolymer that is formed by the condensation of hydrogenated dimer acids and hydrogenated dimer alcohols. The copolymer is capped with Stearic Acid (q.v.). The hydrogenated dimer acids are made from Rapeseed Acid by reacting the unsaturated fatty acids followed by hydrogenation. The dimer alcohols are produced by reducing the acid groups on the hydrogenated dimer acids to convert them to hydroxyl groups."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["5791F04419216B10E3164167CB4BFFCC"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officia