  (99087, '0fdc973e-8227-468f-8367-ba7447b763bb'::uuid, 'POLYACRYLATE-56', 'POLYACRYLATE-56', NULL, NULL, NULL, 'Polyacrylate-56 is a copolymer of Butyl Acrylate and a methacrylate functional siloxane polymer that is made by reacting Hydrogen Dimethicone with 1,3-Epoxy-4-Vinylcyclohexane. The epoxy groups on the siloxane are reacted with Methacrylic Acid to produce the macromonomer.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"0fdc973e-8227-468f-8367-ba7447b763bb","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYACRYLATE-56"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyacrylate-56 is a copolymer of Butyl Acrylate and a methacrylate functional siloxane polymer that is made by reacting Hydrogen Dimethicone with 1,3-Epoxy-4-Vinylcyclohexane. The epoxy groups on the siloxane are reacted with Methacrylic Acid to produce the macromonomer."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["EC0D0712310E0EB33E76A0CD7E03844A"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYACRYLATE-56"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["99087"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["FILM FORMING"],