  (99196, '54cfd68a-2fdf-4f70-8867-55193c8ff565'::uuid, 'POLYURETHANE-101', 'POLYURETHANE-101', NULL, NULL, NULL, 'Polyurethane-101 is a urethane polymer that is prepared by a multi-step process. First, Isophorone Diisocyanate is reacted with polyester polyol made by condensing Adipic Acid with Glycol. The resulting polymer is reacted with Dimethylolpropionic Acid then neutralized with Triethylamine and dispersed into water.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"54cfd68a-2fdf-4f70-8867-55193c8ff565","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.9551744,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-101"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-101 is a urethane polymer that is prepared by a multi-step process. First, Isophorone Diisocyanate is reacted with polyester polyol made by condensing Adipic Acid with Glycol. The resulting polymer is reacted with Dimethylolpropionic Acid then neutralized with Triethylamine and dispersed into water."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["57FDAC40E9A99E0EAE62EAF18094F733"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-101"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["99196"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"ot