  (99244, 'ca0cbaff-c4f4-48ba-8e48-cc864cced0df'::uuid, 'CINNAMOMUM CASSIA BARK/(ALLIUM CHINENSE/LILIUM CANDIDUM) BULB/LONICERA JAPONICA FLOWER/APRICOT KERNEL/(ARTEMISIA PRINCEPS/EUCOMMIA ULMOIDES) LEAF/ GINKGO BILOBA NUT/CITRUS UNSHIU PEEL/(GINGER/LICORICE/PUERARIA THUNBERGIANA/SOPHORA FLAVESCENS) ROOT/COIX LACRYMA-JOBI MA-YUEN SEED/PEPPERMINT EXTRACT', 'CINNAMOMUM CASSIA BARK/(ALLIUM CHINENSE/LILIUM CANDIDUM) BULB/LONICERA JAPONICA FLOWER/APRICOT KERNEL/(ARTEMISIA PRINCEPS/EUCOMMIA ULMOIDES) LEAF/ GINKGO BILOBA NUT/CITRUS UNSHIU PEEL/(GINGER/LICORICE/PUERARIA THUNBERGIANA/SOPHORA FLAVESCENS) ROOT/COIX LACRYMA-JOBI MA-YUEN SEED/PEPPERMINT EXTRACT', NULL, NULL, NULL, 'This is the extract of: the bark of Cinnamomum cassia; the bulbs of Allium chinense and Lilium candidum; the flowers of Lonicera japonica; the kernels of Prunus armeniaca; the leaves of Artemisia princeps and Eucommia ulmoides; the nuts of Ginkgo biloba; the peel of Citrus unshiu; the roots of Glycyrrhiza glabra, Pueraria thunbergiana, Sophora flavescens and Zingiber officinale; the seeds of Coix Lacryma-Jobi Ma-yuen; and the whole plant, Mentha piperita.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"ca0cbaff-c4f4-48ba-8e48-cc864cced0df","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":5.3189683,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["CINNAMOMUM CASSIA BARK/(ALLIUM CHINENSE/LILIUM CANDIDUM) BULB/LONICERA JAPONICA FLOWER/APRICOT KERNEL/(ARTEMISIA PRINCEPS/EUCOMMIA ULMOIDES) LEAF/ GINKGO BILOBA NUT/CITRUS UNSHIU PEEL/(GINGER/LICORICE/PUERARIA THUNBERGIANA/SOPHORA FLAVESCENS) ROOT/COIX LACRYMA-JOBI MA-YUEN SEED/PEPPERMINT EXTRACT"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"