  (99341, 'f606d884-b967-430e-9be1-bb2b3e08af10'::uuid, 'PPG-6 C12-18 ALKETH-11', 'PPG-6 C12-18 ALKETH-11', NULL, NULL, NULL, 'PPG-6 C12-18 Alketh-11 (Formerly PPG-6 C12-18 Pareth-11) is the polyoxyethylene, polyoxypropylene ether of a mixture of synthetic alcohols that conforms generally to the formula below, where R represents an alcohol stem with 12 to 18 carbons in the alkyl chain, x has an average value of 6 and y has an average value of 11.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"f606d884-b967-430e-9be1-bb2b3e08af10","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.0867167,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["PPG-6 C12-18 ALKETH-11"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["PPG-6 C12-18 Alketh-11 (Formerly PPG-6 C12-18 Pareth-11) is the polyoxyethylene, polyoxypropylene ether of a mixture of synthetic alcohols that conforms generally to the formula below, where R represents an alcohol stem with 12 to 18 carbons in the alkyl chain, x has an average value of 6 and y has an average value of 11."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["B2C83A1EC8B12BC6C100067C190D8D06"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["PPG-6 C12-18 ALKETH-11"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["99341"],"annexNo":[],"productTypeBodyParts":[],"phEur