  (99396, '86392ac6-49d7-4e24-9f45-531855ff955f'::uuid, 'SODIUM C14-15 ALKETH-PG SULFONATE', 'SODIUM C14-15 ALKETH-PG SULFONATE', NULL, NULL, NULL, 'Sodium C14-15 Alketh-PG Sulfonate (Formerly Sodium C14-15 Pareth-PG Sulfonate) is the sodium salt of an ethoxylated alkyl glyceryl ether. It conforms generally to the formula below, where R represents the C14-15 fatty alcohol grouping and n has an average value between 1 to 4.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"86392ac6-49d7-4e24-9f45-531855ff955f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9887555,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SODIUM C14-15 ALKETH-PG SULFONATE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Sodium C14-15 Alketh-PG Sulfonate (Formerly Sodium C14-15 Pareth-PG Sulfonate) is the sodium salt of an ethoxylated alkyl glyceryl ether. It conforms generally to the formula below, where R represents the C14-15 fatty alcohol grouping and n has an average value between 1 to 4."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["1030B6763C037A589B5328EB2ACF529D"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SODIUM C14-15 ALKETH-PG SULFONATE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["99396"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherR