  (99552, 'dd7c3c84-4701-4689-8b5b-3afff4ef776b'::uuid, 'BIS-HPMA POLY(1,4-BUTANEDIOL)-9/TMHDI COPOLYMER', 'BIS-HPMA POLY(1,4-BUTANEDIOL)-9/TMHDI COPOLYMER', NULL, NULL, NULL, 'Bis-HPMA Poly(1,4-Butanediol)-9/TMHDI Copolymer is a copolymer of Poly(1,4-Butanediol)-9 and Trimethylhexamethylene Diisocyanate (TMHDI) end-capped with Hydroxypropyl Methacrylate (HPMA).', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"dd7c3c84-4701-4689-8b5b-3afff4ef776b","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-HPMA POLY(1,4-BUTANEDIOL)-9/TMHDI COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-HPMA Poly(1,4-Butanediol)-9/TMHDI Copolymer is a copolymer of Poly(1,4-Butanediol)-9 and Trimethylhexamethylene Diisocyanate (TMHDI) end-capped with Hydroxypropyl Methacrylate (HPMA)."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["1775D409D60503F25EA7EEA304FEEE28"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["BIS-HPMA POLY(1,4-BUTANEDIOL)-9/TMHDI COPOLYMER"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["99552"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["BINDING"],"esDA_IngestDate":["2023-05-23T07:58:06.295+020