  (99629, 'd3615361-2ce8-414d-9ce1-7870a8b07342'::uuid, 'POLYURETHANE-94', 'POLYURETHANE-94', NULL, NULL, NULL, 'Polyurethane-94 is a complex urethane polymer formed by the reaction of Benzoic Acid, Dimethylolpropionic Acid, Isophorone Diisocyanate, Pentaerythritol, Phthalic Anhydride, Trimethylolpropane, Coconut Acid, and a mixture of fatty acids derived from Gossypium Herbaceum Seed Oil. The urethane polymer is reacted with Triethylamine to allow it to be dispersed into water.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"d3615361-2ce8-414d-9ce1-7870a8b07342","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":6.1406865,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["POLYURETHANE-94"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-94 is a complex urethane polymer formed by the reaction of Benzoic Acid, Dimethylolpropionic Acid, Isophorone Diisocyanate, Pentaerythritol, Phthalic Anhydride, Trimethylolpropane, Coconut Acid, and a mixture of fatty acids derived from Gossypium Herbaceum Seed Oil. The urethane polymer is reacted with Triethylamine to allow it to be dispersed into water."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["639CBDCBF297A4723ACAF1D1AABC18BA"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-94"],"esST_FileName":["file.txt"],"casNo":[],"su