  (99635, '21b147d2-a574-445e-83cf-e2a96a31e580'::uuid, 'R-(S-ESCHERICHIA COLI THIOREDOXIN-1 HEPTAPEPTIDE-44 HEXAPEPTIDE-40 OLIGOPEPTIDE-165 SH-POLYPEPTIDE-122)', 'R-(S-ESCHERICHIA COLI THIOREDOXIN-1 HEPTAPEPTIDE-44 HEXAPEPTIDE-40 OLIGOPEPTIDE-165 SH-POLYPEPTIDE-122)', NULL, NULL, NULL, 'r-(s-Escherichia Coli Thioredoxin-1 Heptapeptide-44 Hexapeptide-40 Oligopeptide-165 sh-Polypeptide-122) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from r-Escherichia Coli Thioredoxin-1, Heptapeptide-44, Hexapeptide-40, Oligopeptide-165 and sh-Polypeptide-122. The fusion peptide contains 284 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acid.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"21b147d2-a574-445e-83cf-e2a96a31e580","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["R-(S-ESCHERICHIA COLI THIOREDOXIN-1 HEPTAPEPTIDE-44 HEXAPEPTIDE-40 OLIGOPEPTIDE-165 SH-POLYPEPTIDE-122)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["r-(s-Escherichia Coli Thioredoxin-1 Heptapeptide-44 Hexapeptide-40 Oligopeptide-165 sh-Polypeptide-122) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from r-Escherichia Coli Thioredoxin-1, Heptapeptide-44, Hexapeptide-40, Oligopeptide-165 and sh-Polypeptide-122. The fusion peptide contains 284 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acid."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["2D5529443B8AF96A8FB0944DD6255DD1"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["R-(S-ESCHERICHIA COLI THIOREDOXIN-1 HEPTAPEPTIDE-44 HEXAPEPTIDE-40 OLIGOPEPTIDE-165 SH-POLYPEPTIDE-122)"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["99635"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIMICROBIAL","ANTIOXIDANT","ASTRINGENT","HAIR CONDITIONING","HUMECTANT","SKIN CONDITIONING - MISCELLANEOUS"],"esDA_IngestDate":["2023-05-23T08:05:42.638+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T08:05:42.607+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"21b147d2-a574-445e-83cf-e2a96a31e580. Available at: urn:test"}'::jsonb),
