  (99711, '7c38a959-05df-4e8e-a108-d49c87d6b7f9'::uuid, 'SR-(ESCHERICHIA COLI METHIONYL HEXAPEPTIDE-40 SPIDER POLYPEPTIDE-3) FERMENT EXTRACT', 'SR-(ESCHERICHIA COLI METHIONYL HEXAPEPTIDE-40 SPIDER POLYPEPTIDE-3) FERMENT EXTRACT', NULL, NULL, NULL, 'sr-(Escherichia Coli Methionyl Hexapeptide-40 Spider Polypeptide-3) Ferment Extract is the extract of a single chain fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene which is similar to sr-Spider Polypeptide-3, with Hexapeptide-40, and the initiation code for Methionine. The fusion peptide contains 1760 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"7c38a959-05df-4e8e-a108-d49c87d6b7f9","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SR-(ESCHERICHIA COLI METHIONYL HEXAPEPTIDE-40 SPIDER POLYPEPTIDE-3) FERMENT EXTRACT"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-(Escherichia Coli Methionyl Hexapeptide-40 Spider Polypeptide-3) Ferment Extract is the extract of a single chain fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene which is similar to sr-Spider Polypeptide-3, with Hexapeptide-40, and the initiation code for Methionine. The fusion peptide contains 1760 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["CE2AAC646FB204AF485B1D730D48E8F6"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SR-(ESCHERICHIA COLI METHIONYL HEXAPEPTIDE-40 SPIDER POLYPEPTIDE-3) FERMENT EXTRACT"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["99711"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["FILM FORMING","HAIR CONDITIONING","SKIN PROTECTING","SKIN CONDITIONING - MISCELLANEOUS"],"esDA_IngestDate":["2023-05-23T08:01:24.767+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T08:01:24.745+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"7c38a959-05df-4e8e-a108-d49c87d6b7f9. Available at: urn:test"}'::jsonb),
