  (99725, '856aac86-4ecc-4618-8e2b-39ceacb2ade9'::uuid, 'SILICA POLYSILSESQUIOXANE PROPYLDISULFIDEACETYL TRIPEPTIDE-84', 'SILICA POLYSILSESQUIOXANE PROPYLDISULFIDEACETYL TRIPEPTIDE-84', NULL, NULL, NULL, 'Silica Polysilsesquioxane Propyldisulfideacetyl Tripeptide-84 is Silica that has been condensed with 3-Mercaptopropyltrimethoxysilane. The mercaptan groups from the silsesquioxane are then coupled to Tripeptide-84 using Thioglycolic Acid, which forms a disulfide linkage to the surface-treated silica.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"856aac86-4ecc-4618-8e2b-39ceacb2ade9","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.3189683,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SILICA POLYSILSESQUIOXANE PROPYLDISULFIDEACETYL TRIPEPTIDE-84"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Silica Polysilsesquioxane Propyldisulfideacetyl Tripeptide-84 is Silica that has been condensed with 3-Mercaptopropyltrimethoxysilane. The mercaptan groups from the silsesquioxane are then coupled to Tripeptide-84 using Thioglycolic Acid, which forms a disulfide linkage to the surface-treated silica."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["341B9F6F35BF39492A8D0C5FC9BA0495"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SILICA POLYSILSESQUIOXANE PROPYLDISULFIDEACETYL TRIPEPTIDE-84