  (99780, 'cee39ccc-7169-4eda-8596-fdab4d1fad93'::uuid, 'SH-PENTAPEPTIDE-6 SP AMIDE', 'SH-PENTAPEPTIDE-6 SP AMIDE', NULL, NULL, NULL, 'sh-Pentapeptide-6 SP Amide is a single chain human peptide produced synthetically to be identical to a portion of the protein, Adiponectin, and contains 5 amino acids consisting of glycine, leucine, phenylalanine and tyrosine in which the C-terminus is an amide. The parent protein contains a maximum of 244 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"cee39ccc-7169-4eda-8596-fdab4d1fad93","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-PENTAPEPTIDE-6 SP AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Pentapeptide-6 SP Amide is a single chain human peptide produced synthetically to be identical to a portion of the protein, Adiponectin, and contains 5 amino acids consisting of glycine, leucine, phenylalanine and tyrosine in which the C-terminus is an amide. The parent protein contains a maximum of 244 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["4E250017F4372AD4705232940DA7427A"],"cosmeticRestricti