  (99789, '8a34ddbe-81ca-42cc-90e1-37c6af2a6901'::uuid, 'TULIPA GESNERIANA/KAURMANNIANA MERISTEM CELL LYSATE FILTRATE EXTRACT', 'TULIPA GESNERIANA/KAURMANNIANA MERISTEM CELL LYSATE FILTRATE EXTRACT', NULL, NULL, NULL, 'Tulipa Gesneriana/Kaurmanniana Meristem Cell Lysate Filtrate Extract is the extract of a filtrate obtained after the lysis of the cultured meristem cells of the hybrid formed between Tulipa gesneriana and Tulipa kaurmanniana. The accepted scientific name for this hybrid is Tulipa gesneriana x Tulipa kaufmanniana.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"8a34ddbe-81ca-42cc-90e1-37c6af2a6901","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["TULIPA GESNERIANA/KAURMANNIANA MERISTEM CELL LYSATE FILTRATE EXTRACT"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Tulipa Gesneriana/Kaurmanniana Meristem Cell Lysate Filtrate Extract is the extract of a filtrate obtained after the lysis of the cultured meristem cells of the hybrid formed between Tulipa gesneriana and Tulipa kaurmanniana. The accepted scientific name for this hybrid is Tulipa gesneriana x Tulipa kaufmanniana."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["7B84BDC2B400BE22D1140A2CF17CD397"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["TULIPA GESNERIA