  (99800, '3f4586f5-2620-44b8-8313-32edfa343c3a'::uuid, 'SH-HEPTAPEPTIDE-11 SP AMIDE', 'SH-HEPTAPEPTIDE-11 SP AMIDE', NULL, NULL, NULL, 'sh-Heptapeptide-11 SP Amide is the single chain human peptide synthetically produced to be identical to a portion of the protein, Pro-Opiomelanocortin and contains 7 amino acids consisting of arginine, glycine, lysine, proline and valine, in which the C-terminus is an amide. Pro-Opiomelanocortin contains a maximum of 267 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"3f4586f5-2620-44b8-8313-32edfa343c3a","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-HEPTAPEPTIDE-11 SP AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Heptapeptide-11 SP Amide is the single chain human peptide synthetically produced to be identical to a portion of the protein, Pro-Opiomelanocortin and contains 7 amino acids consisting of arginine, glycine, lysine, proline and valine, in which the C-terminus is an amide. Pro-Opiomelanocortin contains a maximum of 267 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["0EBAF08C40EDC4A6F6D05A4832639E95"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SH-HEPTAPEPTIDE-11 SP AMIDE"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["99800"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - MISCELLANEOUS"],"esDA_IngestDate":["2023-05-23T08:05:34.298+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T08:05:34.261+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"3f4586f5-2620-44b8-8313-32edfa343c3a. Available at: urn:test"}'::jsonb),
  (99803, '6fd2866f-545a-4fe1-b9ae-ba7335321064'::uuid, 'SR-(HEXAPEPTIDE-40 OLIGOPEPTIDE-202 SH-POLYPEPTIDE-135 HEPTAPEPTIDE-57 SH-OLIGOPEPTIDE-1)', 'SR-(HEXAPEPTIDE-40 OLIGOPEPTIDE-202 SH-POLYPEPTIDE-135 HEPTAPEPTIDE-57 SH-OLIGOPEPTIDE-1)', NULL, NULL, NULL, 'sr-(Hexapeptide-40 Oligopeptide-202 sh-Polypeptide-135 Heptapeptide-57 sh-Oligopeptide-1) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from Hexapeptide-40, Oligopeptide-202, sh-Polypeptide-135, Heptapeptide-57 and sh-Oligopeptide-1. The fusion peptide contains 239 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"6fd2866f-545a-4fe1-b9ae-ba7335321064","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SR-(HEXAPEPTIDE-40 OLIGOPEPTIDE-202 SH-POLYPEPTIDE-135 HEPTAPEPTIDE-57 SH-OLIGOPEPTIDE-1)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-(Hexapeptide-40 Oligopeptide-202 sh-Polypeptide-135 Heptapeptide-57 sh-Oligopeptide-1) is a single chain recombinant peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from Hexapeptide-40, Oligopeptide-202, sh-Polypeptide-135, Heptapeptide-57 and sh-Oligopeptide-1. The fusion peptide contains 239 amino 