  (99884, '2a72cbae-fbc6-4855-9dd4-fd055139a6e4'::uuid, 'SILICA POLYSILSESQUIOXANE PROPYLDISULFIDEACETYL PENTAPEPTIDE-4', 'SILICA POLYSILSESQUIOXANE PROPYLDISULFIDEACETYL PENTAPEPTIDE-4', NULL, NULL, NULL, 'Silica Polysilsesquioxane Propyldisulfideacetyl Pentapeptide-4 is Silica that has been condensed with 3-Mercaptopropyltrimethoxysilane. The mercaptan groups from the silsesquioxane are then coupled to Pentapeptide-4 using Thioglycolic Acid which forms a disulfide linkage to the surface-treated silica.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"2a72cbae-fbc6-4855-9dd4-fd055139a6e4","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.7249496,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SILICA POLYSILSESQUIOXANE PROPYLDISULFIDEACETYL PENTAPEPTIDE-4"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Silica Polysilsesquioxane Propyldisulfideacetyl Pentapeptide-4 is Silica that has been condensed with 3-Mercaptopropyltrimethoxysilane. The mercaptan groups from the silsesquioxane are then coupled to Pentapeptide-4 using Thioglycolic Acid which forms a disulfide linkage to the surface-treated silica."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["BC04DCB9CCFF08A4BF4471779AD6BD5C"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SILICA POLYSILSESQUIOXANE PROPYLDISULFIDEACETYL PENTAPEP