  (99886, 'd9676e84-33ff-45dc-b239-3191f3e49728'::uuid, 'SILICA POLYSILSESQUIOXANE PROPYLDISULFIDEACETYL HEXAPEPTIDE-87 AMIDE', 'SILICA POLYSILSESQUIOXANE PROPYLDISULFIDEACETYL HEXAPEPTIDE-87 AMIDE', NULL, NULL, NULL, 'Silica Polysilsesquioxane Propyldisulfideacetyl Hexapeptide-87 Amide is Silica that has been condensed with 3-Mercaptopropyltrimethoxysilane. The mercaptan groups from the silsesquioxane are then coupled to Hexapeptide-87 Amide using Thioglycolic Acid which forms a disulfide linkage to the surface-treated silica.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"d9676e84-33ff-45dc-b239-3191f3e49728","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.3189683,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SILICA POLYSILSESQUIOXANE PROPYLDISULFIDEACETYL HEXAPEPTIDE-87 AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Silica Polysilsesquioxane Propyldisulfideacetyl Hexapeptide-87 Amide is Silica that has been condensed with 3-Mercaptopropyltrimethoxysilane. The mercaptan groups from the silsesquioxane are then coupled to Hexapeptide-87 Amide using Thioglycolic Acid which forms a disulfide linkage to the surface-treated silica."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["EA77F398829632F5A5EC62B385F28995"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SILICA POLYSIL