  (99887, '912bcd38-d08f-40a7-8ec9-d95f95406ddd'::uuid, 'S-CUTIBACTERIUM ACNES OLIGOPEPTIDE-1', 'S-CUTIBACTERIUM ACNES OLIGOPEPTIDE-1', NULL, NULL, NULL, 's-Cutibacterium Acnes Oligopeptide-1 is a single chain protein synthetically produced to be identical to a portion of the protein, Foldase YidC, which is found in the bacteria, Cutibacterium acnes. The peptide contains 14 amino acids. The parent protein, Foldase YidC, contains a maximum of 359 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"912bcd38-d08f-40a7-8ec9-d95f95406ddd","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-CUTIBACTERIUM ACNES OLIGOPEPTIDE-1"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Cutibacterium Acnes Oligopeptide-1 is a single chain protein synthetically produced to be identical to a portion of the protein, Foldase YidC, which is found in the bacteria, Cutibacterium acnes. The peptide contains 14 amino acids. The parent protein, Foldase YidC, contains a maximum of 359 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["8C0B0D905398FB9BCE2A0447747216F4"],"cosmeticRestr