  (99890, '0b7dae2d-70d1-429f-b75f-e0c00e1d3307'::uuid, 'PALMITOYL SH-HEPTAPEPTIDE-12 SP', 'PALMITOYL SH-HEPTAPEPTIDE-12 SP', NULL, NULL, NULL, 'Monograph development in progress. Palmitoyl sh-Heptapeptide-12 SP is the product obtained by the reaction of palmitoyl chloride and sh-Heptapeptide-12 SP.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"0b7dae2d-70d1-429f-b75f-e0c00e1d3307","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["PALMITOYL SH-HEPTAPEPTIDE-12 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Monograph development in progress. Palmitoyl sh-Heptapeptide-12 SP is the product obtained by the reaction of palmitoyl chloride and sh-Heptapeptide-12 SP."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["293B7121CEFEB858A0305C3E6F6F52D1"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["PALMITOYL SH-HEPTAPEPTIDE-12 SP"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["99890"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN PROTECTING","SKIN CONDITIONING - MISCELLANEOUS"],"esDA_IngestDate":["2023-05-23T08:28:51.087+0200"],"currentVersion":[],"corporate-search-version":["102"],"url":["urn:test"],"esST_U