  (99891, '4d63bf96-b1cb-4326-9abb-ae3ebf0323c1'::uuid, 'S-RATTLESNAKE DECAPEPTIDE-1 AMIDE', 'S-RATTLESNAKE DECAPEPTIDE-1 AMIDE', NULL, NULL, NULL, 's-Rattlesnake Decapeptide-1 Amide is a single chain protein synthetically produced based on a sequence from Acidic Phospholipase A2 Beta which is found in the Eastern diamondback rattlesnake, Crotalus adamanteus. The parent protein, Acidic Phospholipase A2 Beta, has a maximum of 138 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"4d63bf96-b1cb-4326-9abb-ae3ebf0323c1","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-RATTLESNAKE DECAPEPTIDE-1 AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Rattlesnake Decapeptide-1 Amide is a single chain protein synthetically produced based on a sequence from Acidic Phospholipase A2 Beta which is found in the Eastern diamondback rattlesnake, Crotalus adamanteus. The parent protein, Acidic Phospholipase A2 Beta, has a maximum of 138 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["8313BDC02131C590481AF718DB155132"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"i