  (99892, 'e6dfd5d6-1949-4bd7-96d0-c9f56d4a81ef'::uuid, 'S-HIBISCUS SABDARIFFA OLIGOPEPTIDE-1 AMIDE', 'S-HIBISCUS SABDARIFFA OLIGOPEPTIDE-1 AMIDE', NULL, NULL, NULL, 's-Hibiscus Sabdariffa Oligopeptide-1 Amide is a single chain peptide synthetically produced based on a 12 amino acid sequence from Roseltide which is found in Hibiscus sabdariffa. Roseltide has a maximum of 27 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"e6dfd5d6-1949-4bd7-96d0-c9f56d4a81ef","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-HIBISCUS SABDARIFFA OLIGOPEPTIDE-1 AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Hibiscus Sabdariffa Oligopeptide-1 Amide is a single chain peptide synthetically produced based on a 12 amino acid sequence from Roseltide which is found in Hibiscus sabdariffa. Roseltide has a maximum of 27 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["327A92A31A9474AD42BA69F1283093AC"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["S-HIBISCUS SABDARIFFA OLIGOPEPTIDE-1 AMIDE"],"esS