  (99893, '4845d88d-bfe7-4e21-b72f-0d11108dac32'::uuid, 'S-FROG OLIGOPEPTIDE-1 AMIDE', 'S-FROG OLIGOPEPTIDE-1 AMIDE', NULL, NULL, NULL, 's-Frog Oligopeptide-1 Amide is a single chain peptide synthetically produced based on a 14 amino acid sequence from Temporin-1DRb which is found in the California red-legged frog, Rana draytonii. Temporin-1DRb has a maximum of 63 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"4845d88d-bfe7-4e21-b72f-0d11108dac32","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["S-FROG OLIGOPEPTIDE-1 AMIDE"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Frog Oligopeptide-1 Amide is a single chain peptide synthetically produced based on a 14 amino acid sequence from Temporin-1DRb which is found in the California red-legged frog, Rana draytonii. Temporin-1DRb has a maximum of 63 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["EADCC9E79D10883A36648095C057ED91"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["S-FROG OLIGOPEPTIDE-1 AMIDE"],"esST_FileName":["file.t